export default [{"id":153,"question":"ما حكم الهدية في الإسلام؟ هل تُقبل أو تُرد؟","title":"ما حكم الهدية؟ ومتى تُقبل أو تُرد؟","answer":"الجواب: الأصل في الهدايا أنها تُقبل، كان النبيُّ ﷺ يقبل الهدية ويُثِيب عليها. رواه البخاريُّ من حديث عائشة.\nإلا إذا كانت ثمنًا لدِينه: كالذي يدفع للقاضي ليجور وليخون وليحيف، أو لموظفٍ ليخون، فلا يأخذ ما يُهدى للعمَّال ليحيفوا ولا يؤدُّوا الحقَّ، فتكون رشوةً.\nأما الهدايا في أصلها فهي قربة، ومن أسباب التَّحاب، ولكن ينبغي لمَن أُهدي إليه شيءٌ أن يُثيب المُهدي، وأن يُقابله مقابل هديته، إذا كانت من باب الهدايا، أما إذا كانت من باب الصَّدقات فلها شأنٌ آخر.","link":"https://binbaz.org.sa/fatwas/3690/ما-حكم-الهدية-ومتى-تقبل-او-ترد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0146.mp3","categories":["الهبة والعطية"]},{"id":325,"question":"ما حكم أخذ الهدايا عند التَّبرع بالدم؟","title":"حكم أخذ الهدايا مقابل التبرَّع بالدم","answer":"الجواب: الدم لا يُباع، الرسول ﷺ نهى عن بيع الدم، وعن ثمن الدم، فإذا أهديتَ دمًا فلا تأخذ عنه شيئًا، لا هديةً، ولا غيرها. وإذا قدر أنَّك أخذتَ شيئًا فتصدّق به على بعض الفقراء، ولا تستعمله، ولا تأكله، ثبت عن رسول الله ﷺ أنه نهى عن ثمن الدم، والهدية ثمنٌ، ما أعطوك إيَّاها إلا لأجل الدَّم.","link":"https://binbaz.org.sa/fatwas/4412/حكم-اخذ-الهدايا-مقابل-التبرع-بالدم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0378.mp3","categories":["الهبة والعطية"]},{"id":857,"question":"هل يجوز لأب أن يكتب جزءًا من تركته لأحد أبنائه دون الآخر؟","title":"حكم كتابة الأب جزءًا من تَرِكَته لأحد أبنائه","answer":"الجواب: ليس للأب ولا للأم أن يخصَّ أحدًا من أولاده بشيءٍ، يقول النبي ﷺ: اتَّقوا الله واعدلوا بين أولادكم، فليس للوالد ولا للوالدة تخصيص بعض الأولاد بشيءٍ، لا في الحياة، ولا في الوصية، بل يجب التَّعديل: اتَّقوا الله واعدلوا بين أولادكم.","link":"https://binbaz.org.sa/fatwas/20891/حكم-كتابة-الاب-جزءا-من-تركته-لاحد-ابناىه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0686هل يجوز لأب أن يكتب جزءً من تركته لأحد أبناءه دون الأخر؟ ابن باز فتاوى المحاضرات.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":1288,"question":"هل يجوز إهداء القرآن أو المصحف المُترجم باللغة الإنجليزية لبعض الأطباء غير المسلمين بقصد الدَّعوة؟","title":"ما حكم إهداء ترجمة للقرآن لغير المسلم؟","answer":"الجواب:\nأولًا: أحبك الله الذي أحببتنا له، ونسأل الله أن يجعلنا وإياكم من المتحابين بجلاله، يقول النبيُّ ﷺ: سبعةٌ يُظلهم الله في ظلِّه يوم لا ظلَّ إلا ظله: إمام عادل، وشاب نشأ في عبادة الله، ورجل قلبه معلَّقٌ بالمساجد، ورجلان تحابَّا في الله، اجتمعا على ذلك، وتفرَّقا عليه، ورجل دعته امرأةٌ ذات منصبٍ وجمالٍ –يعني: إلى الزنا- فقال: إني أخاف الله، ورجل تصدَّق بصدقةٍ فأخفاها، حتى لا تعلم شماله ما تُنفق يمينه، ورجل ذكر الله خاليًا –يعني: ما عنده أحد- ففاضت عيناه يعني: بكاء من خشية الله جلَّ وعلا، ويقول النبيُّ ﷺ: يقول الله يوم القيامة: أين المتحابُّون بجلالي؟ اليوم أُظلهم في ظلِّي يوم لا ظلَّ إلا ظلي، نسأل الله أن يجعلنا وإيَّاكم منهم.\nأما نفس المصحف غير المترجم فلا، النبي نهى عن السفر بالقرآن إلى أرض العدو، قال: لئلا تناله أيديهم، لكن إذا أُعطي تفسيرًا أو مترجمًا فلا بأس بالترجمة والتفسير، فإذا أُعطي القرآن المترجم أو تفسير القرآن الذي في ضمنه القرآن فلا بأس، لكن لا يُعطى القرآن المجرد.","link":"https://binbaz.org.sa/fatwas/21347/ما-حكم-اهداء-ترجمة-للقران-لغير-المسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1090هل يجوز أهداء ترجمة للقرآن لغير المسلم؟ ابن باز فتاوى.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":1320,"question":"بالنسبة للوالد هل له أن يرجع في صدقته على ولده؟","title":"هل للوالد الرجوع في صدقته على ولده؟","answer":"الجواب:\nله الرجوع بنص النبي عليه الصلاة والسلام، إلا الوالد يعطي ولده له الرجوع.","link":"https://binbaz.org.sa/fatwas/21411/هل-للوالد-الرجوع-في-صدقته-على-ولده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للوالد الرجوع في صدقته على ولده.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":1490,"question":"سائلة تقول: فتحتُ حسابًا في بنك الراجحي، فاتصل عليَّ قسم النساء وأعطوني هديةً ساعة مقابل هذا الرصيد، فماذا أفعل بها؟","title":"حكم هدايا البنوك للعملاء مقابل الرصيد","answer":"الجواب:\nرصيد أيش؟\nس: رصيد في البنك، فقد وجدوا أنَّ أموالها كثيرة فقالوا: أنت تستحقين هذه الهدية: ساعة قيمة، تقول السائلة: أنا استلمتها فماذا أفعل بها؟\nج: الأحوْط لها والذي يظهر أنها تبيعها وتتصدق بها، وإلا تردها عليهم حتى يفهموا أنَّ هذا ما هو طيب.","link":"https://binbaz.org.sa/fatwas/21588/حكم-هدايا-البنوك-للعملاء-مقابل-الرصيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في هدايا البنوك.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":1996,"question":"الإشهاد في الهبة مستحب وإلا واجب؟","title":"حكم الإشهاد في الهبة","answer":"الجواب:\nنعم، أشهد على هذا غيري لأجل قد يرجع الواهب، وقد تتغير الأمور، فالإشهاد أقل أحواله الاستحباب، مثل الإشهاد في البيع وَأَشْهِدُوا إِذَا تَبَايَعْتُمْ [البقرة:282] أقل أحواله الاستحباب.\nس: سماها صدقة (ورجع أبي في تلك الصدقة)؟\nالشيخ: على ولده...\nس: تسمى الهبة والعطية \"صدقة\"؟\nالشيخ: إذا أراد الأجر صارت صدقة.\nس: الإمام أو القاضي أو الوالي لا يَشْهد؟\nالشيخ: إذا أشهدهم أشهدهم على عطية أو على بيع، ما في حكمها، هذه شهادة.\nس: بالنسبة لإعطائه المكافأة تشجيعًا له؟\nالشيخ: لا يخصه بشيء إلا النفقة الواجبة، النفقة الواجبة لا بأس، كُلٌّ يُعطى على قدره، أما إذا كان مجرد تشجيع هذا على حفظ وإلا كذا، لا، لا يعطيهم، يشجّعهم بالكلام، وإلا إذا أعطاه تشجيعًا يُعْطِي الآخرين مثله.","link":"https://binbaz.org.sa/fatwas/22112/حكم-الاشهاد-في-الهبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الإشهاد في الهبة.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":1998,"question":"التسوية بين الأولاد حتى لو كان بعضهم يصلي وبعضهم لا يصلي؟","title":"حكم التسوية في الأعطية للولد الذي لا يصلي","answer":"الجواب:\nلا، الكافر ما له حق، إذا كان كافرًا ما له حق. الكلام في أولاده المسلمين، الكافر الذي يترك الصلاة كافر، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/22114/حكم-التسوية-في-الاعطية-للولد-الذي-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يتساوى الأولاد في الأعطية إذا كان أحدهم يصلي والآخر لا يصلي.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":2150,"question":"هل الشَّرْهات والمَنَاخ تُعتبر من بيت المال؟","title":"هل \"الشّرْهة\" و\"المَنَاخ\" تُعتبر من بيت المال؟","answer":"الجواب:\nهذا من سؤال السلطان من بيت المال، فالشيء المعتاد لا بأس به، إلا أن يسأل سلطانًا أو في أمرٍ لا بد منه، كما تقدم.","link":"https://binbaz.org.sa/fatwas/22269/هل-الشرهة-والمناخ-تعتبر-من-بيت-المال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سؤال السلطان من بيت المال والمسألة في الكتب الخاصَّة بالتَّوزيع.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":2176,"question":"مدير إدارة يأتي إليه الموظفون بالحلا والبسكوت وبعض المأكولات وبعض المشروبات كالشاي والقهوة؟","title":"حكم إهداء الهدايا لمدير الإدارة","answer":"الجواب:\nيهدون إليه من أموالهم أم من الإدارة؟\nس: يهدون له من أموالهم.\nج: لا، لا يأخذ منهم شيئًا، يُشبه الأمير، ولا يأخذ شيئًا؛ لأنه قد يُسبب له مشاكل.","link":"https://binbaz.org.sa/fatwas/22297/حكم-اهداء-الهدايا-لمدير-الادارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم إهداء الهدايا لمدير الإدارة.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":2206,"question":"بالنسبة لهذا المَنَاخ: هناك بعض الشّرهات التي تُسمَّى هذه الأيام، فإذا أردتُ شرهةً مثلًا أجعل للموظف خمسة آلاف ريـال حتى يتوسَّط لي عند الدولة، فهل هذا جائز؟","title":"حكم مَن يدفع لموظف ليتوسَّط في مال الدولة","answer":"الجواب:\nلا، الشفاعة ما يُؤخذ عليها شيء، أما إذا كانت لك معاملة وتطلب أن يكون لك مناخ، ووكلتَ إنسانًا بمتابعة المعاملة، فهو مثل الدّلال، يُعطى أجره عن متابعته، أما الشفاعة فلا، الشفاعة ما يصلح، ما يُعطى شيئًا.","link":"https://binbaz.org.sa/fatwas/22329/حكم-من-يدفع-لموظف-ليتوسط-في-مال-الدولة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم ما يأتي للإنسان من الأموال التي تقرها الدولة.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":2241,"question":"أحد الإخوان يُهدَى إليه كثيرًا ويردّ الهدايا، لا هو في مركزٍ وليس له سبب حتى يرد الهدية؟","title":"حكم مَن يَرُدُّ الهدايا مِن غير سبب ظاهر","answer":"الجواب:\nالسُّنة قبول الهدية، والإثابة عليها، فالنبي عليه الصلاة والسلام يقول: تهادوا تحابّوا، وكان يقبل الهديةَ، ويُثِيب عليها، ولا يردّها إلا لعِلَّةٍ.\nس: وقوله: لا تُهدي لي فتُكلّفني فوق طاقتي؟\nج: إذا كان يُهدي له أموالًا يردّها عليه، لا بأس، إذا كان يريد العِوض من هديته.\nس: لا، ما يُريد العِوض، لكنه يردّها كثيرًا، هكذا حتى ضاق صدرُ أخيه؟\nج: يمكن أنه يتَّهمه بأنه يُريد العِوض.\nس: ما يتّهمه أبدًا.\nج: السُّنة قبول الهدية إلا إذا كان من علَّةٍ.\nس: مَن أخذ الهديةَ وبعد ذلك أهداها، هل هناك شيء في هذا؟\nج: لا بأس، فهذا ملكه يتصرّف فيه كيف يشاء.","link":"https://binbaz.org.sa/fatwas/22364/حكم-من-يرد-الهدايا-من-غير-سبب-ظاهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من أهدي له هدايا ويردها.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":2940,"question":"في الحديث أن النبي ﷺ وَجَد على صفية في نفسه شيئًا فقالت صفية رضي الله عنها لعائشة رضي الله عنها: هل لك أن تُرضي النبي ﷺ عني وأهَبُ لك يومي، والحديث طويل، فالحديث يرد عليه إشكال: أنه هل تُقبل الهدية في الشفاعة؟","title":"ما حكم الهدية التي تُعطى في الشفاعة؟","answer":"الجواب: لا، إلا إذا سمح بها الزوج، إذا سمح بها الزوج؛ فلا بأس.\nس: عائشة رضي الله عنه قبلت يوم صفية رضي الله عنها؟\nالشيخ: يوم سَوْدة، سودة لما أراد طلاقها، قالت: يا رسول الله أمسكني في حبالك ويومي لعائشة، فقبل النبي ﷺ. فإذا قبل النبي من الزوجة لا بأس.\nس: ما يعتبر من قبول الهدية في الشفاعة؟\nالشيخ: لا ما في شيء؛ لأن هذا إسقاط حق.","link":"https://binbaz.org.sa/fatwas/23096/ما-حكم-الهدية-التي-تعطى-في-الشفاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تقبل الهدية في الشفاعة.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":3143,"question":"هناك بعض محطات البنزين يضعون لمن يشتري منهم بمائة وعشرين ريالًا بنزين غسيل سيارة مجانًا، فما حكم هذا الغسيل؟","title":"حكم عرض المحطات غسيل السيارة مجانًا","answer":"الجواب: تَرْكُه أحسن؛ لأن هذا يرغبون في السَّوْم حتى يتعطل الآخرون، تَرْك هذا أحسن وأوْلى.\nس: وإن فعل ما يُنْكر عليه؟\nالشيخ: والله تَرْكُه أوْلى، الأحوط عندي؛ لأنه قد يَبْذِل أموالًا لعله يُحَصّل هذا، نعم.","link":"https://binbaz.org.sa/fatwas/23305/حكم-عرض-المحطات-غسيل-السيارة-مجانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم ما يفعله بعض المحطات لمن يشتري منهم بمبلغ معين غسيل سيارة مجانا.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":3540,"question":"أعطى فلانًا عطية، وهو أراد أن يُعطي غيره؟","title":"هل يجوز الرجوع في الأعطية؟","answer":"الجواب: ليس له الرجوع في العطية، إلا الوالد فيما يعطي ولده.\nس: يعطي غيره؟\nالشيخ: لا، ليس له الرجوع، الرسول ﷺ نهى عن الرجوع في الهدية.","link":"https://binbaz.org.sa/fatwas/23722/هل-يجوز-الرجوع-في-الاعطية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز الرجوع في الأعطية.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":3674,"question":"بالنسبة لقبول الهدية..؟","title":"هل قبول الهدية واجب أم مستحب؟","answer":"الجواب: محل نظر، والمشهور عند العلماء الاستحباب، وعلى المُهدَى له أن يقابل الهدية، كان النبي ﷺ يقبل الهدية ويثيب عليها، يعني يعطيهم مقابلًا؛ لأن بعض الناس قد يهدي للمقابل، فإذا قبلها أعطاه مقابل ذلك، يعني أثابهم عليها، وفي الحديث الآخر: تهادوا تحابوا.","link":"https://binbaz.org.sa/fatwas/23863/هل-قبول-الهدية-واجب-ام-مستحب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الهدية وقبولها.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":3757,"question":"إنسان موظف، عميل عنده...؟","title":"حكم الهدايا للعمال والموظفين","answer":"الجواب: كل الهدايا مثل ما سمعت، إلا إذا كان بينك وبينه معرفة سابقة وهدايا سابقة لقرابة أو مجاورة أو نحو ذلك، فالعادة السابقة لا تدخل في هذا.\nس: إذا جاءت عاملاً في العمل مكافأة؟\nالشيخ: إذا كان من ولي الأمر لا بأس، سمعت كلام النبي: أفلا قعد في بيت أبيه وأمه فيرى هل يهدى إليه؟ هو ما أهدى إليه إلا لأجل ولايته هذه.\nس: وإن كان لا تقتضي المصلحة إلا بذلك؟\nالشيخ: ولو زعم أن المصلحة تقتضي ذلك، لا يعطيه شيئًا، يصبر ويأخذه بالطرق المعروفة، الطرق الشرعية.\nس: حكمها من الغُل؟\nالشيخ: الغُل من الغلول، الغِل: الحقد، والغِل: القيد الذي يكون في العنق، والغلول ما يأخذه الإنسان من الغنيمة وغيرها بغير حق.","link":"https://binbaz.org.sa/fatwas/23949/حكم-الهدايا-للعمال-والموظفين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الهدايا للعمال.mp3","categories":["الهبة والعطية","أحكام الموظفين"]},{"id":4195,"question":"هل يدخل الجد في أحفاده؟","title":"هل يدخل الجد في الأمر بالعدل بين الأولاد؟","answer":"الجواب: كلهم أولاده، حتى أولاد بنيه يعدل بينهم.","link":"https://binbaz.org.sa/fatwas/24453/هل-يدخل-الجد-في-الامر-بالعدل-بين-الاولاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث اتقوا الله واعدلوا في أولادكم، هل يدخل الجد.mp3","categories":["الهبة والعطية"]},{"id":4196,"question":"لو كانت العطية لا تصلح إلا له، ولا تصلح لغيره؟","title":"حكم العطية التي لا تصلح إلا لواحد من الأولاد","answer":"الجواب: المقصود مثل ما قال ﷺ: اتقوا الله واعدلوا بين أولادكم فإذا سمحوا وهم مرشدين، إذا شاورهم وسمحوا فلا بأس،...... إذا سمحوا لأخيهم لحاجة وهم مرشدون؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/24454/حكم-العطية-التي-لا-تصلح-الا-لواحد-من-الاولاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم العطية إذا كانت لا تصلح إلا لواحد فقط من الأولاد.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":4878,"question":"رجوع المرأة في هبتها لزوجها؟","title":"هل للمرأة الرجوع في هبتها لزوجها؟","answer":"إذا كانت لها أسباب كأن تعطيه تخاف أن يطلق وطلق؛ ترجع، أما إذا كانت أعطته لفقره وحاجته، ما هو خوف من طلاق؛ ليس لها الرجوع، تعمها الأحاديث. المقصود أن ينظر في القرائن وأن يتقي الله؛ فإذا كانت القرائن أنها أعطته خوفًا من شره أو خوفًا من طلاقه أو خوفًا أن يتزوج، فإذا خالف ما رأت يرد عليها الهدية.","link":"https://binbaz.org.sa/fatwas/25382/هل-للمراة-الرجوع-في-هبتها-لزوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للمرأة الرجوع في هبتها لزوجها.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":4879,"question":"هل الهدية تُهدى وتُباع؟","title":"هل الهدية تُهدى وتُباع؟","answer":"نعم.\nس: بعضهم يقول: لا تهدى ولا تباع؟\nج: لا، هذا كلام جاهل.","link":"https://binbaz.org.sa/fatwas/25383/هل-الهدية-تهدى-وتباع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الهدية تهدى وتباع.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":4880,"question":"من كان يتعامل بالربا هل تُقبل هديته؟","title":"هل تُقبل هدية من يتعامل بالربا؟","answer":"ولو، إذا كان ما هو كل ماله ربا. الله أباح لنا طعام اليهود وهم يتعاملون بالربا، والنبي ﷺ اشترى منهم طعامًا ورهنهم درعه.\nأما إذا كنت تعلم أنها من مال الربا أو كل ماله ربا لا تأخذها.\nس: هو يعمل في بنك وليس له مورد إلا من هذا البنك؟\nج: لا تقبلها.","link":"https://binbaz.org.sa/fatwas/25384/هل-تقبل-هدية-من-يتعامل-بالربا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تقبل هدية من يتعامل بالربا.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":5006,"question":"المَنَاخ إذا كان يأتي لرجلٍ وهو في غنًى عنه؟","title":"حكم مَن يأتيه مال من الدولة وهو غني عنه","answer":"الجواب: ولو، فالمَنَاخ هذا من بيت المال، والمهاجرون والأنصار فيهم الأغنياء، وعمر فرض لهم عادةً سنويةً، فهو على حسب ما تُقرّه الدولة: إن رأت قطعه تقطعه، وإن رأت أن تُعطيه مَن خلفه، إن كان خلفه أيتام أو فقراء، أو تقطعه؛ فهذا يرجع إلى الدولة.","link":"https://binbaz.org.sa/fatwas/28808/حكم-من-ياتيه-مال-من-الدولة-وهو-غني-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من يأتيه مال من الدولة وهو غني عنه.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":5184,"question":"ما حكم الهدية في الإسلام؟ هل تُقبل أو تُرد؟","title":"ما حكم الهدية في الإسلام؟","answer":"الجواب: الأصل في الهدايا أنها تُقبل، كان النبيُّ ﷺ يقبل الهدية ويُثِيب عليها. رواه البخاريُّ من حديث عائشة. إلا إذا كانت ثمنًا لدِينه: كالذي يُدفع للقاضي ليجور وليخون وليحيف، أو لموظفٍ ليخون، فلا يأخذ. ما يُهدى للعمَّال ليحيفوا ولا يؤدُّوا الحقَّ؛ تكون رشوةً. أما الهدايا في أصلها فهي قربة، ومن أسباب التَّحاب، ولكن ينبغي لمَن أُهدي إليه شيءٌ أن يُثيب المُهدي، وأن يُقابله مقابل هديته، إذا كانت من باب الهدايا، أما إذا كانت من باب الصَّدقات فلها شأنٌ آخر.","link":"https://binbaz.org.sa/fatwas/30121/ما-حكم-الهدية-في-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 146.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":5473,"question":"مَن يتعامل بالربا هل تُقبل هديته أو عطيته؟","title":"هل تُقبل هدية مَن يتعامل بالربا؟","answer":"الجواب: إذا كانت أمواله كلها ربا لا، أما إذا كانت له أعمال ربوية وأعمال أخرى فلا بأس؛ مثلما اشترى النبي من اليهود وهم يتعاطون الربا، اشترى منهم طعامًا؛ لأنهم يأكلون الربا، وعندهم أعمال أخرى، أما إذا كان لا، إنسان ما عنده دخل إلا الربا فلا، لا تُقبل معاملته. س: من كان عنده مال مختلط بين الحلال والحرام هل يخشى عليه من عدم؟ ج: المختلط لا بأس أن يُعامل، وهو عليه أن يتَّقي الله ويحذر. س: هل يخشى عليه من عدم قبول الدعاء؟ ج: وهو من أسباب عدم قبول الدعاء، أكل الربا وأكل الحرام من أسباب عدم قبول الدعاء.[1]","link":"https://binbaz.org.sa/fatwas/31351/هل-تقبل-هدية-من-يتعامل-بالربا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/reyath_alsalhin 008.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":5670,"question":"ما الواجب على الوالد في عطيته وهبته لأولاده إذا كان فيهم ذكور وإناث؟ هل يجب أن يُعطي البنت نصف ما يُعطي الولد؟","title":"هل يلزم في أعطية الوالد أن تكون وفق الميراث؟","answer":"الجواب: الواجب العدل؛ لأنَّ الرسول يقول: اتَّقوا الله واعدلوا بين أولادكم، فلا بدَّ أن يُسوي بينهم: لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ [النساء:11] مثل الإرث، فإذا أعطى الرجلَ ألفًا يُعطي المرأة خمسمئة، لا بدَّ من التعديل بينهم، إلا إذا كانوا مُرشدين وسمحوا لواحدٍ يُعطى زيادةً، وهم مُرشدون وسمحوا عن طيب نفسٍ فلا بأس. أما إذا كانوا غير مُرشدين لا، لا بدَّ من التعديل، يُسوي بينهم، ولا يُعطي هذا ويدع هذا، الرجل والمرأة، المرأة لها نصف الرجل، وإن كانت مُتزوجة، لا بدَّ أن يُسوي بينها وبين إخوتها، ولا يظلم، يعدل بين الجميع، الرسول يقول: اتَّقوا الله واعدلوا بين أولادكم. س: وهل إذا اشترى سيارةً أو أرضًا أن يفعل مثله مع بقية إخوانه؟ ج: سيارة أو غيرها، إلا إذا كانت باسمه عارية، يذهب بها للمدرسة، وهي باسم الوالد، ما هي بعطيَّة، لكن يذهب بها للمدرسة ويرجع، وهي باسم الوالد؛ لا بأس. أما عطية لا، لا يُعطيه عطية دون إخوته.[1]","link":"https://binbaz.org.sa/fatwas/31707/هل-يلزم-في-اعطية-الوالد-ان-تكون-وفق-الميراث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aldurus almuhima 016.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":5733,"question":"هل يجوز استلام العائدات السنوية المسماة المناخ إذا كنت موظفًا، وأستلم راتبًا شهريًا؟ وهل يستحقها أيضًا أولادي؟","title":"حكم استلام التبرع السنوي المسمى بالمناخ","answer":"الجواب:  هذا تبرع من الدولة لا بأس به، تبرع من الدولة لكل الرعية، باديًا وحاضرًا، فإذا أخذها فلا بأس، وإذا مات فهي لورثته إلا إذا منعتها الحكومة، وقطعتها فهي إليها، وإلا فهذه المناخ للعموم، والذي يموت تكون للورثة بعده.","link":"https://binbaz.org.sa/fatwas/1049/حكم-استلام-التبرع-السنوي-المسمى-بالمناخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_66.mp3","categories":["الهبة والعطية","الآداب والأخلاق المحمودة"]},{"id":5748,"question":"هل يجوز استلام العائدات السنوية المسماة المناخ إذا كنت موظفًا، وأستلم راتبًا شهريًا؟ وهل يستحقها أيضًا أولادي؟","title":"حكم استلام التبرع السنوي المسمى بالمناخ","answer":"الجواب:  هذا تبرع من الدولة لا بأس به، تبرع من الدولة لكل الرعية، باديًا وحاضرًا، فإذا أخذها فلا بأس، وإذا مات فهي لورثته إلا إذا منعتها الحكومة، وقطعتها فهي إليها، وإلا فهذه المناخ للعموم، والذي يموت تكون للورثة بعده.","link":"https://binbaz.org.sa/fatwas/1049/حكم-استلام-التبرع-السنوي-المسمى-بالمناخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_66.mp3","categories":["الهبة والعطية","الآداب والأخلاق المحمودة"]},{"id":6334,"question":"وأحد الإخوة يسأل: لقد اشتركت في مسابقة القرآن الكريم في شهر رمضان المبارك، والذي كان يقدم من إذاعة القرآن الكريم، وقد فزت بجائزة قدرها عشرة آلاف ريال، وأنا لم أسمع النتيجة بنفسي، ولكن أذاعوها، وإنما كتبوا بعض الأحباب، وقد استلمت الجائزة إلا أن قلبي لم يرتح لذلك، مالم أعطهم بشارة على ما يقول المثل؛ لأن الفضل لله، ثم لهم، فهل لو أعطيتهم شيئًا من هذا يوافق سنة رسول الله؟","title":"حكم الهبة لمن بشرك بخير","answer":"الجواب: ما نعلم فيه شيئًا، لا بأس، كعب بن مالك لما بشره بعض الصحابة بتوبة الله عليه، أعطاه ثوبين، ثوبين كانا عليه، فإذا أعطى المبشر بخير ينفعه، أعطاه دراهم، أو ملابس؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/1932/حكم-الهبة-لمن-بشرك-بخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_717.mp3","categories":["الهبة والعطية","الآداب والأخلاق المحمودة"]},{"id":6342,"question":"وأحد الإخوة يسأل: لقد اشتركت في مسابقة القرآن الكريم في شهر رمضان المبارك، والذي كان يقدم من إذاعة القرآن الكريم، وقد فزت بجائزة قدرها عشرة آلاف ريال، وأنا لم أسمع النتيجة بنفسي، ولكن أذاعوها، وإنما كتبوا بعض الأحباب، وقد استلمت الجائزة إلا أن قلبي لم يرتح لذلك، مالم أعطهم بشارة على ما يقول المثل؛ لأن الفضل لله، ثم لهم، فهل لو أعطيتهم شيئًا من هذا يوافق سنة رسول الله؟","title":"حكم الهبة لمن بشرك بخير","answer":"الجواب: ما نعلم فيه شيئًا، لا بأس، كعب بن مالك لما بشره بعض الصحابة بتوبة الله عليه، أعطاه ثوبين، ثوبين كانا عليه، فإذا أعطى المبشر بخير ينفعه، أعطاه دراهم، أو ملابس؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/1932/حكم-الهبة-لمن-بشرك-بخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_717.mp3","categories":["الهبة والعطية","الآداب والأخلاق المحمودة"]},{"id":6350,"question":"وأحد الإخوة يقول: لو ميزت أحد أبنائي بمال أكتبه له؛ لأنني لم أتح له الفرصة التي أتحتها لإخوته، أو لأنه لم يتزوج مثلهم، أو لأنه مريض، أو كفيف البصر، فهل أستطيع أعطي له شيئًا من مالي؟","title":"حكم تخصيص أحد الأبناء بشيء من المال","answer":"الجواب: النبي ﷺ يقول: اتقوا الله، واعدلوا بين أولادكم، أفلا يسرك أن يكونوا في البر سواء؟ قال: بلى، قال: فلا إذًا، وقال : إني لا أشهد على جور.  فالمقصود: أن الواجب على الإنسان، سواء ذكر، أو أنثى، الأب، أو الأم عليهم أن يعدلوا بين أولادهم، وليس لهم أن يجوروا، فلا يعطي الابن، ويدع البنت، ولا يعطي بعض الأولاد، ويدع الباقين، ولا يعطي بعض البنات، ويدع الباقين، بل عليه أن يعدل بينهم جميعاً، ولو كان أحدهم ليس من الحذق مثل الآخر، لو كان واحد حاذق، وواحد ليس بحاذق، وواحد عنده أموال، وواحد ما عنده أموال يسوي بينهم، ويعدل بينهم. لكن النفقة لا بأس بها إذا كان واحد فقير، ما عنده أسباب وواحد مغنيه الله؛ ينفق على الفقير حتى يغنيه الله؛ لأن هذا من وجوب النفقة، ومن البر. فالفقير، والكفيف، والمريض الذي ما عنده أسباب، ووالده يقدر على الإنفاق، ينفق عليه، وليس هذا من الجور، والأولاد الذين أغناهم الله، وعندهم أموال ليسوا بحاجة إلى النفقة، وإذا زوجهم يزوج الجميع، إلا إذا كان بعض المتزوجين قد أغناهم الله؛ فيزوج نفسه مما أعطاه الله، والعاجز يزوجه والده مما أعطاه الله، إذا كان عاجزًا مثل النفقة.  أما أن يخص واحدًا لأجل كذا، أو لأجل كذا، وإلا كلهم سواء في المال لا، لا يخص هذا؛ لأنه كفيف، أو يخص هذا لأنه أبر، أو يخص هذا لأن عنده مثلاً أولاد كثير، أو ما أشبه ذلك، إلا إذا كان فقيراً.  المقصود: لا يخص أحدًا دون أحد إلا لأمر شرعي مثل: النفقة على الفقير العاجز، ولا يستطيع العمل، أو لأنه أراد أن يسوي بينهم في العطية، فأعطى هذا، ثم أعطى الباقين، لا لأجل التخصيص، بل ليعيطهم مثله، أو ما أشبه ذلك مما فيه التسوية.  السؤال: يا شيخ بالنسبة للتسوية بين الذكر، والأنثى؟ الجواب:  على حسب الميراث، هذا أرجح القولين.","link":"https://binbaz.org.sa/fatwas/1933/حكم-تخصيص-احد-الابناء-بشيء-من-المال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_718.mp3","categories":["الهبة والعطية","الآداب والأخلاق المحمودة"]},{"id":6371,"question":"وأحد الإخوة يسأل: لقد اشتركت في مسابقة القرآن الكريم في شهر رمضان المبارك، والذي كان يقدم من إذاعة القرآن الكريم، وقد فزت بجائزة قدرها عشرة آلاف ريال، وأنا لم أسمع النتيجة بنفسي، ولكن أذاعوها، وإنما كتبوا بعض الأحباب، وقد استلمت الجائزة إلا أن قلبي لم يرتح لذلك، مالم أعطهم بشارة على ما يقول المثل؛ لأن الفضل لله، ثم لهم، فهل لو أعطيتهم شيئًا من هذا يوافق سنة رسول الله؟","title":"حكم الهبة لمن بشرك بخير","answer":"الجواب: ما نعلم فيه شيئًا، لا بأس، كعب بن مالك لما بشره بعض الصحابة بتوبة الله عليه، أعطاه ثوبين، ثوبين كانا عليه، فإذا أعطى المبشر بخير ينفعه، أعطاه دراهم، أو ملابس؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/1932/حكم-الهبة-لمن-بشرك-بخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_717.mp3","categories":["الهبة والعطية","الآداب والأخلاق المحمودة"]},{"id":6393,"question":"عندي أولاد، وبنات، وزوجتين، وعندي بنت عندها بعض المرض، هل يحق لي أن أعطيها بعض المال، وهل يجوز ذلك، أرجو إفادتي جزاكم الله خيرًا؟","title":"حكم هبة المال لأحد الأبناء لمرضه","answer":"الجواب: البنت المريضة تعالجها، وتنفق عليها ما دامت فقيرة، ومحتاجة، ولكن لا تخصها بشيء دون أخواتها، إذا كان لها أخوات، وإخوة لا تخصها بشيء، لا بيت، ولا مال يحفظ لها خاصة، الله يقوم برزق الجميع .  ولكن الفقير يعطى الفقير، ينفق عليه، والمريض يعالج، وليس في هذا محاباة، المحاباة أن تعطيه شيئًا سوى ذلك، وتفاضل بينهم، أو تخص بعضهم دون بعض، قال النبي ﷺ: اتقوا الله واعدلوا بين أولادكم أما علاج المريض، والإنفاق على الفقير؛ فهذا ليس بمحاباة، فالغني قد استغنى بما أعطاه الله من المال.","link":"https://binbaz.org.sa/fatwas/1963/حكم-هبة-المال-لاحد-الابناء-لمرضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_750.mp3","categories":["الهبة والعطية","الأخلاق المذمومة"]},{"id":6415,"question":"جاءنا من أحد الإخوة ملخصه: أهديت لابني الأكبر قطعة أرض مبانٍ، على شرط شفوي على أن خيرها لجميع الأسرة، وكتبت له بذلك، ولكنه عمّر عليها، واستغلها، ولم يعط لأحد منا شيئًا منها، وامتنع، وطلبته بتنفيذ شرع الله، وأن يستغلها طول عمري، ثم تكون ميراثًا لكل حقه، ولكنه هددني، وشتمني، وتطاول عليّ، وسب الدين، ومزق كتاب منهاج المسلم، وطرحه، فهل عليّ وزر فيما حدث؟","title":"وجوب المساواة بين الأبناء في العطية والهدية","answer":"الجواب: عليك أن ترفع أمره إلى المحكمة، وأن توضح للمحكمة بما جرى، والمحكمة فيها الخير -إن شاء الله- والبركة، هذه مسائل خصومة بينك، وبين ولدك، وهذه من عقوبات التخصيص، هذه من عقوباتك لما تخصصه بشيء، الولد ما يخصص بشيء دون .. اتقوا الله، واعدلوا بين أولادكم فلما وقع منك هذا الشيء، والتساهل؛ صار هذا من نوع العقوبات.  فالواجب عليك أن تخاصمه، وأن ترفع أمره إلى ولاة الأمور؛ حتى يخلصوك مما حصل من العقوق، والجحد للحق، وإنكاره، وحتى تعدل بين أولادك.","link":"https://binbaz.org.sa/fatwas/2134/وجوب-المساواة-بين-الابناء-في-العطية-والهدية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_783.mp3","categories":["الهبة والعطية","الأخلاق المذمومة"]},{"id":6537,"question":"بالنسبة لقبول الهدايا يجوز قبول الهدايا؟","title":"حكم قبول الهدايا","answer":"الجواب: الهدايا فيها تفصيل، إذا كانت هدية لا يترتب عليها شر، وليست بقشيشًا، ولا رشوة، بل هدية من صاحب،  ومن. السؤال:.. الجواب: هذا فيه تفصيل .....\n\nالسؤال: عيد الميلاد الذي يسمونه عيد الميلاد .. قبول الهدية هذا فيه شيء؟  الجواب:  لا، في عيد النصارى ما يجوز قبول الهدايا فيه؛ لأنها تشجيع لأعيادهم، لا يجوز كذلك، لا يجوز حضورها، ولا مشاركتهم فيها، ولا تشجيعهم عليها، ولا معاونة فيها، ولا إهداؤهم شيئًا لأعيادهم، كل هذا معناه إقرارهم على المنكر وموافقتهم عليه. السؤال: طيب وإن كنت أنا صاحب عمل، وعندي نصارى ..؟ الجواب: الذين معهم .. الطالب: عندهم خمسة وعشرون في العيد بتاعهم ذا ممكن يستأذنوا نصف يوم بحجة إنهم يروحوا يعيدوا عندهم ..؟ الجواب: لا ما جئت بهم للأعياد، أنا جئت بهم لعملي، هذا منكر حتى في دينهم منكر.","link":"https://binbaz.org.sa/fatwas/2382/حكم-قبول-الهدايا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_915.mp3","categories":["الهبة والعطية","الأخلاق المذمومة"]},{"id":6552,"question":"رجل يريد أن يتنازل لزوجته عن بيته إكرامًا لها، وتطييبًا لخاطرها، ومكافأة لإخلاصها معه طول حياته، وتحملها المشاق معه، فما حكم ذلك؟","title":"حكم تنازل الزوج عن بيته لزوجته","answer":"الجواب: لا بأس إذا تنازل عن بيته لها، عطية لها صحيحة بسبب إكرامها له، وخدمتها له، وعملها الطيب، فلا بأس أن يتنازل لها عن بيته إذا كان صحيحًا، لا مريضًا، أما إذا كان مريضًا ليس له أن يتنازل لها؛ لأنها وارثة، وليس لها شيء، وليس له أن يوصي بها وصية، الوارث لا وصية له، لكن إذا كان صحيحًا، وأراد أن يعيطها بيته، وهو صحيح سليم -لا مريض- ولا يوصي وصية، بل يعطيها عطية ناجزة؛ لأنها امرأة صالحة، خدمته، وقامت بحقه، وأحسنت عشرته، فهذا من مكارم الأخلاق، ومن محاسن الأعمال، ولا بأس به. السؤال: لو قصد ذلك أنه ليس له أبناء ذكور يمكن حتى إخوته لا يرثونه مثلًا؟ الشيخ: سواء كان له أبناء، أو ما له أبناء، ما دام صحيحًا سليمًا، غير مريض، له أن يعطي زوجته، ويعطي غيرها. السؤال: تعد هذه وصية؟ الشيخ: لا ما هي بوصية، هذه ناجزة إذا كان وصية لا، إذا كان أوصى لها ما يجوز الوصية، لا وصية لوارث لكن إذا كان أعطاها إياه عطية ناجزة، وهو حي، وسليم صحيح.","link":"https://binbaz.org.sa/fatwas/2407/حكم-تنازل-الزوج-عن-بيته-لزوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_934.mp3","categories":["الهبة والعطية","الآداب والأخلاق المحمودة"]},{"id":6582,"question":"رجل يريد أن يتنازل لزوجته عن بيته إكرامًا لها، وتطييبًا لخاطرها، ومكافأة لإخلاصها معه طول حياته، وتحملها المشاق معه، فما حكم ذلك؟","title":"حكم تنازل الزوج عن بيته لزوجته","answer":"الجواب: لا بأس إذا تنازل عن بيته لها، عطية لها صحيحة بسبب إكرامها له، وخدمتها له، وعملها الطيب، فلا بأس أن يتنازل لها عن بيته إذا كان صحيحًا، لا مريضًا، أما إذا كان مريضًا ليس له أن يتنازل لها؛ لأنها وارثة، وليس لها شيء، وليس له أن يوصي بها وصية، الوارث لا وصية له، لكن إذا كان صحيحًا، وأراد أن يعيطها بيته، وهو صحيح سليم -لا مريض- ولا يوصي وصية، بل يعطيها عطية ناجزة؛ لأنها امرأة صالحة، خدمته، وقامت بحقه، وأحسنت عشرته، فهذا من مكارم الأخلاق، ومن محاسن الأعمال، ولا بأس به. السؤال: لو قصد ذلك أنه ليس له أبناء ذكور يمكن حتى إخوته لا يرثونه مثلًا؟ الشيخ: سواء كان له أبناء، أو ما له أبناء، ما دام صحيحًا سليمًا، غير مريض، له أن يعطي زوجته، ويعطي غيرها. السؤال: تعد هذه وصية؟ الشيخ: لا ما هي بوصية، هذه ناجزة إذا كان وصية لا، إذا كان أوصى لها ما يجوز الوصية، لا وصية لوارث لكن إذا كان أعطاها إياه عطية ناجزة، وهو حي، وسليم صحيح.","link":"https://binbaz.org.sa/fatwas/2407/حكم-تنازل-الزوج-عن-بيته-لزوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_934.mp3","categories":["الهبة والعطية","الآداب والأخلاق المحمودة"]},{"id":6736,"question":"من المعلوم أن العدل بين الأولاد في الأعطية واجب، ولكن قد يحتاج أحدهم ما لا يحتاج الآخر، فالكبير يحتاج مصاريف أكثر من الصغير، والبنت قد تحتاج بعض الذهب، فكيف يكون العدل بينهم؟","title":"كيفية العدل بين الأولاد في العطية والنفقة","answer":"الجواب: الأعطية التي فيها العدل، المنحة الزائدة على النفقة، الرسول ﷺ قال: اتقوا الله، واعدلوا بين أولادكم يعني في العطايا الزائدة، أما الإنفاق عليهم، فكل ينفق عليه بقدر حاجته، الكبير له نفقة، والرضيع له نفقة،  والذي بين هذين له نفقة، فليسوا سواء، فهذه نفقة واجبة، ينفق عليهم بقدر حاجتهم، فالكبير بحاجة إلى ملابس غير ملابس الصغير، في حاجة إلى الزواج، إذا كان ما عنده مال؛ يزوجه، بحاجة إلى السكن، والصغير حاجته دون [ذلك] فكل من الأولاد يعطى حاجته على حسب حاله، ولا .. تعديل، التعديل في ذلك أنه يعطى حاجته هذا التعديل. أما العطايا الزائدة على النفقة، هذا هو محل التعديل، ولا يخص أحدًا بشيء، فيعطي هذا .. وهذا ما يعطيه، هذا يعطيه سيارة، وهذا ما يعطيه سيارة، لا، يساوي بينهم، لكن في نفقتهم في الملابس، والمآكل، والمشارب، والسفر، ونحو ذلك، كل له قدر حاجته.","link":"https://binbaz.org.sa/fatwas/2607/كيفية-العدل-بين-الاولاد-في-العطية-والنفقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1103.mp3","categories":["تربية الأولاد","النفقات","الهبة والعطية"]},{"id":7118,"question":"والدي يملك أموالًا وعقارات، وله ثلاث زوجات، وقام بتزويجي أنا وأخي الذي يصغرني في السن، وكنا ولازلنا نسكن مع والدنا، وأصبحنا نملك الأولاد، عندها قال والدي: كل واحد يأخذ قطعة أرض، ويبنيها بقرض من الدولة، وقد ذهب والدي وإخوتي إلى المحكمة لإفراغ الأرض بأسمائنا، ولكنهم فوجئوا برفض القاضي حيث قال: إن هناك لهم إخوة كثيرون، وهم صغار من بنين وبنات، ولا بد أن يعطى كل واحد منهم قطعة أرض، أو يمنعوا جميعًا، علمًا بأني أعمل بوظيفة ودخلي لا يمكنني من شراء أرض، ما هو الحكم إذا أنا أعطيت والدي قطعتين أرض قد منحت لي من قبل الدولة في مكانين مختلفين من المملكة مقابل أن يفرغ لي أحد الأراضي التي في الرياض، على أن لدي شعور على أن الوالد إذا فعل بي هذا الشيء؛ فهو من أجل أن يمكنني الأرض التي في الرياض؟","title":"حكم عطية الوالد بعض أولاده دون الآخرين","answer":"الجواب:\n\nالذي قاله القاضي صواب، لأن الرسول  قال: اتقوا الله واعدلوا بين أولادكم فليس له أن يعطي بعض الأولاد أراضي، ولا يعطي الآخرين، فعليه أن يعمهم جميعًا، أو يتركهم جميعًا، هكذا أمر النبي ﷺ: اتقوا الله واعدلوا بين أولادكم.\n\nفإذا كان يريد نفعكم؛ يبيع عليكم بيعًا، يبيع عليكم الأراضي بيعًا، مثل ما يبيع على الناس من غير محاباة، يبيع عليكم الأرض بما تساوي عند أهل الخبرة بيعًا عليكم مؤجلًا، مثل ما يباع على الأجانب، يباع عليكم وتكون في ذمتكم؛ حتى يتيسر لكم الوفاء مثل ما يبيع على أناس أجانب.\n\nوإذا باعها عليكم بيعًا بأراضي أخرى من غير محاباة، بل بأراضي تكون قيمتها معادلة لقيمة الأرض التي أعطاكم بغير محاباة، ولا حيلة، فلا بأس بذلك؛ لأنه يجوز أن يبيع عليكم كما يبيع على غيركم.\n\nالسؤال: وإذا كانوا راضين؟\n\nالجواب: إن كانوا كبارًا، وراضين؛ لا بأس، أما إن كانوا صغارًا ما لهم رضا، إن كانوا مرشدين، ووافقوا مثل عنده عشرة أو ثمانية، وأعطى اثنين أو ثلاثة، ورضي الباقون، وهم مرشدون؛ لا بأس، أما إن كانوا صغارًا، أو مجانين، أو معتوهين ليس له ذلك.","link":"https://binbaz.org.sa/fatwas/3147/حكم-عطية-الوالد-بعض-اولاده-دون-الاخرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1505.mp3","categories":["النفقات","الهبة والعطية","تربية الأولاد"]},{"id":7126,"question":"رجل يعمل في إدارة، فساعد رجلًا لتخليص عمله في تلك الإدارة، وأهدى هذا الرجل للرجل الذي يعمل في الإدارة كتبًا بعد إنجاز العمل، علمًا أن هذه الكتب كتب عليها: وقف لله تعالى، نرجو من سماحتكم الرد على هذا، هل هذه رشوة، أو ما هي؟","title":"حكم الهدية مقابل خدمة معاملة في مكتب إدارة","answer":"الجواب:\n\nالموظف الذي يسعى في تخليص معاملة أخيه لا يأخذ رشوة، ولا يأخذ مالًا، ولا يأخذ عطية؛ لأن هذه في الغالب تكون رشوة باسم الهدية، ولو أنها كتب موقوفة لا يأخذ منها شيئًا أبدًا؛ لأنها في الغالب تكون رشوة، ومساعدة له حتى يعطل عمل غيره، ويقدم هذا الرجل، أو يعطيه أشياء بغير حق، ويعمل له بغير حق، فلا يعطي الموظف شيئًا أبدًا.","link":"https://binbaz.org.sa/fatwas/3164/حكم-الهدية-مقابل-خدمة-معاملة-في-مكتب-ادارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1522.mp3","categories":["الهبة والعطية","الأخلاق المذمومة"]},{"id":8098,"question":"سؤاله الثالث في هذه الرسالة يقول: أنا اشتغل في المزرعة وموجود فيها عنب ونخل وخضر، وأنا أحمل من هذه الأشياء، مع العلم أننا كلنا على حساب المعزب يقول: وإذا حضر أحد أصدقائنا أطعمناه وبدون علم المعزب، وإذا طلبنا منهم شيء أعطونا من مزرعتهم، وإذا طلبوا منا كذلك شيء نعطيهم من مزرعتنا، وإذا قلنا لهم: هذا حرام، قالوا: هذا أكلنا على حسابه، ونحن نعطيكم من أكلنا، هل يجوز لنا ذلك، وفقكم الله إلى ما فيه خير الدنيا والدين؟","title":"حكم إعطاء أجير المزرعة ضيوفه من المزرعة","answer":"الجواب: هذا فيه تفصيل الكلام فيه إجمال، أما كون الضيف يعطى من الفاكهة الموجودة من غير خبنة يعني لا يحمل شيئاً بل يأكل معكم فلا بأس إن شاء الله، قد جاء في الحديث ما يدل على ذلك، أما أن تهدوه إلى الناس فلا، إلا بإذن صاحب المزرعة، لا تهدوه لأحد إلا بإذن صاحب المزرعة، لكن من زاركم وقدمتم لهم شيء مما في المزرعة من عنب أو بطيخ أو رطب فلا بأس، بحيث يأكل فقط لا يحمل معه شيئاً، ولا تهدوا له شيئاً، بل يأكل معكم من هذا الذي يسره الله، هذا لا بأس به إن شاء الله، أما أن يتخذ معه شيء يخرج به أو تهدوا له شيئاً فلا، إلا بإذن صاحب المزرعة.","link":"https://binbaz.org.sa/fatwas/5892/حكم-اعطاء-اجير-المزرعة-ضيوفه-من-المزرعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_086/08607.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":8218,"question":"إحدى الأخوات المستمعات من الوشم، بعثت تقول: لها أخوان توأمان؛ أخت وأخ وتسأل تقول: هل يجب العدل في التعامل معهما وفي إعطائهما كل شيء؟","title":"حكم العدل بين الإخوة","answer":"الجواب: لا يجب، إنما هذا في الأولاد، النبي ﷺ قال: اتقوا الله واعدلوا بين أولادكم أما الإخوة والخالات والعمات والأقارب الآخرون فلا يجب العدل بينهم، لكن يكون المؤمن حكيماً إذا كان عدم العدل بينهم قد يسبب مشاكل وشحناء فينبغي للمعطي أن يعدل ويتحرى العدل حتى لا تقع بينه وبين قراباته مشاكل، فإذا كان أخوك وأختك، لو أعطيت الأخ وتركت الأخت، قد يكون بينك وبينها مشاكل فأحسني إن الله يحب المحسنين، أعطيها وأعطيه، وجودي عليهما جميعاً، وهكذا لو أعطيتها وتركتيه قد يكون هناك مشاكل فأحسني إليهما جميعاً، أما إذا كان لا يترتب شيء ولا يحصل ضرر، فلا مانع أن تعطيها حاجتها، أو تعطيه كذلك هو، أو تخصيه بشيء أو تخصيها بشيء لا بأس بهذا. نعم.\nالمقدم: بارك الله فيكم، ربما تنطلق أختنا إلى قضية العدل بين التوأمين خاصة؟\nالشيخ: لا، ما يلزم لا في التوأمين ولا في غيرهما، إنما هذا في الأولاد، ليس لها أن تخص بعض الأولاد دون بعض لا الذكور ولا الإناث لقول النبي ﷺ: اتقوا الله واعدلوا بين أولادكم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6039/حكم-العدل-بين-الاخوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_096/09611.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":8224,"question":"إحدى الأخوات المستمعات من الوشم، بعثت تقول: لها أخوان توأمان؛ أخت وأخ وتسأل تقول: هل يجب العدل في التعامل معهما وفي إعطائهما كل شيء؟","title":"حكم العدل بين الإخوة","answer":"الجواب: لا يجب، إنما هذا في الأولاد، النبي ﷺ قال: اتقوا الله واعدلوا بين أولادكم أما الإخوة والخالات والعمات والأقارب الآخرون فلا يجب العدل بينهم، لكن يكون المؤمن حكيماً إذا كان عدم العدل بينهم قد يسبب مشاكل وشحناء فينبغي للمعطي أن يعدل ويتحرى العدل حتى لا تقع بينه وبين قراباته مشاكل، فإذا كان أخوك وأختك، لو أعطيت الأخ وتركت الأخت، قد يكون بينك وبينها مشاكل فأحسني إن الله يحب المحسنين، أعطيها وأعطيه، وجودي عليهما جميعاً، وهكذا لو أعطيتها وتركتيه قد يكون هناك مشاكل فأحسني إليهما جميعاً، أما إذا كان لا يترتب شيء ولا يحصل ضرر، فلا مانع أن تعطيها حاجتها، أو تعطيه كذلك هو، أو تخصيه بشيء أو تخصيها بشيء لا بأس بهذا. نعم.\nالمقدم: بارك الله فيكم، ربما تنطلق أختنا إلى قضية العدل بين التوأمين خاصة؟\nالشيخ: لا، ما يلزم لا في التوأمين ولا في غيرهما، إنما هذا في الأولاد، ليس لها أن تخص بعض الأولاد دون بعض لا الذكور ولا الإناث لقول النبي ﷺ: اتقوا الله واعدلوا بين أولادكم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6039/حكم-العدل-بين-الاخوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_096/09611.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":9366,"question":"أخت لنا من السودان بعثت برسالة مطولة وضمنتها اثني عشر سؤالًا متنوعة من أحد أسئلتها: تقول: لي أربعة أطفال، أكبرهم في السابعة من عمره، كانت أمنيتي قبل أن يرزقني الله بهم إن كانت لي ذرية سأحاول بقدر الإمكان تعليمهم أمور الدين وتهيئة الجو الإسلامي لهم، وفعلًا أخذت أعلمهم ومنهم من يحفظ كثيرًا من القرآن الكريم والأحاديث حتى القصص لا يعلمون غير قصص الأنبياء، ولم أدخل عليهم أي جهاز من الأجهزة الحديثة كالمسجل أو الفيديو أو ما أشبه ذلك، إلا أنهم يعيشون في جو غريب تمامًا، وبدءوا يستنكرون كل ما عدا ما في منزلنا أو كل ما عدا ما يسمعون منا، وبدءوا يعيشون في شيء من الازدواجية وترجو التوجيه جزاكم الله خيرًا؟","title":"نصيحة في تربية الأبناء","answer":"الجواب: قد أحسنت في تعليمهم وتوجيههم، وعليك أن تكملي أنت ووالدهم وإخوتهم الكبار وغير ذلك من أقاربهم، عليكم أن تلاحظوهم حتى لا يضرهم ما حولهم من المجتمع، أنت على خير، وأبوهم على خير في التعليم والتوجيه والإرشاد والتربية الإسلامية، ولكن لابد من اختلاطهم بمن حولهم، فعليكم بالحرص عليهم وتوجيههم إلى الخير، وتحذيرهم مما قد يسمعون من الباطل، أو يشاهدون من الباطل حولهم حتى لا يتأثروا به، والله جل وعلا هو الموفق الهادي، وإنما عليكم أن تفعلوا المستطاع: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] وأنتم على خير إن شاء الله وسوف ينفع الله بجهودكم. نعم.","link":"https://binbaz.org.sa/fatwas/7530/نصيحة-في-تربية-الابناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_186/18606.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية","فتاوى متنوعة"]},{"id":9594,"question":"الرسالة التالية وصلت من إخوة سودانيين مقيمين بالمملكة يقولون في سؤالهم الأول:هل يمكن أن يشيد الإنسان صدقة جارية ويهبها لأحد الأصدقاء أو الأقرباء غير الأب والأم، وهل يمكن أن يصل أجرها إليه، أفيدونا أفادكم الله؟","title":"حكم تشييد صدقة جارية وهبتها","answer":"الجواب: قول السائل هل يمكن أن يشيد صدقة جارية معنى التشييد لم أفهمه، فإن كان المراد بالتشييد ............. ويحدث أرضًا صدقة جارية أو إنارة تكون صدقة جارية أو دكان يعني حانوت يكون صدقة جارية فلا بأس يسبله ويجعل غلته لأبيه أو أمه أو أقاربه تنفعهم الصدقة تنفع الميت والحي جميعًا، أو يجعل غلته في إصلاح المساجد أو في مواساة الفقراء والمحاويج أو في قضاء دين المديونين أو في بناء أربطة للفقراء وما أشبه ذلك، هذه يقال لها: صدقة جارية، ويقال لها: وقف، ويقال لها: إسبال ويقال لها ....... قال النبي ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له.\nأما إن كان أراد بالتشييد الإخراج ، يعني يريد أن يخرج مالًا من ماله ويخرج نقود أو طعام أو ملابس من ماله يتصدق بها على بعض أصدقائه أو على بعض أقربائه أو على بعض جيرانه المحتاجين أو على غيرهم فكذلك لا بأس بهذا والأجر يلحق، الأجر يلحق الميت والحي إذا أخلصوها لله والتقرب إلى الله بذلك فإنه ينفعه ما أخرجه من ..... أو من ملابس أو أطعمة أو لحوم إذا أعطاها بعض الفقراء أو بعض الأصدقاء للتقرب إلى الله أو لأنه فقير أو ما أشبه ذلك من هذه الأسباب الشرعية فكل هذا ينفع الميت والحي.","link":"https://binbaz.org.sa/fatwas/7760/حكم-تشييد-صدقة-جارية-وهبتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_193/19305.mp3","categories":["الوقف","الهبة والعطية"]},{"id":9732,"question":"هذه رسالة وصلت من السائل (ح. ظ. ف) يقول: سماحة الشيخ ما حكم الإسلام -في نظركم- في كتابة الوالدين لما يملكون لأولادهم قبل الممات؟","title":"حكم توزيع الأب التركة على الأولاد حال حياته","answer":"الجواب: هذه فيه تفصيل: إن كان عطية لأولادهم يعطونهم عطية وهم أصحاء سالمون لا بأس عطية بشرط العدل للذكر مثل حظ الأنثيين، لا يخصون بعضهم دون بعض، يعطونهم جميعًا للذكر مثل حض الأنثيين لا بأس، أما وصية بعد الموت إذا .. وصية من مرض فلا إذا كان هناك ورثة آخرون كالزوجة أو الزوج أو الوالدين لا يوصي بوصية للورثة الورثة لا، يقول النبي ﷺ: إن الله قد أعطى كل ذي حق حقه فلا وصية لوارث وإذا أراد أن يوصي فليس له إلا الثلث، يوصي بالثلث أو أقل. نعم. لغير الورثة.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7887/حكم-توزيع-الاب-التركة-على-الاولاد-حال-حياته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_272/27221.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":9845,"question":"تقول أيضاً: لنا قريب يقدم لنا بعض الحاجات المنزلية البسيطة، وهذه الحاجات مما اعتاد الناس أن يبيعوها، فقدمنا له نقوداً فلم يأخذها واعتبر أن هذه الحاجة هدية، وبعد مدة استعملنا هذه الحاجات تبين لنا أنه قد سرقها من شركة أجنبية يعمل حارساً عندها، فما حكم استعمالنا لهذه الحاجة بعد معرفتنا أنها مسروقة؟","title":"حكم استعمال الهدية إذا ثبت أنها مسروقة","answer":"الجواب: متى علمتم أن هذه الحاجات مسروقة، فالواجب عليك ردها إلى أصحابها؛ لأن هذا منكر وإنكار المنكر واجب، فإذا علمتم أنها مسروقة فردوها إلى أهلها، وأخبروه أن هذا لا يجوز له، وأن الواجب عليه أداء الأمانة مع الشركة ومع غير الشركة، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/8013/حكم-استعمال-الهدية-اذا-ثبت-انها-مسروقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_262/26205.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":10033,"question":"يقول: قمت بإحضار بعض الناس لكي يعملوا في إحدى دول الخليج وأخذت منهم بعض النقود برضاهم، فهل يحق لي ذلك وإن كان غير ذلك فماذا أفعل؟","title":"حكم أخذ المال عن الشفاعة في المنافع","answer":"الجواب: إذا كنت اتفقت معهم على مال معلوم من بلادهم حتى توصلهم إلى الخليج وتقوم بما يجب من قيمة التذاكر وغير ذلك، هذا شيء لا حرج فيه، لأنك أديت عنهم مالاً حتى توصلهم إلى إحدى دول الخليج بسبب خدمتك لهم، وسعيك لهم في إيصالهم إلى دول الخليج حتى يعملوا هناك، أما إن كانت الأموال التي أخذتها من أجل الشفاعة لهم في أن يعملوا عند فلان أو عند فلان والنفقة على حسابهم لكن أعطوك المال لأجل الشفاعة اللي عند فلان أو فلان حتى يستخدمهم فلا ينبغي لك أن تأخذ المال، في الحديث: من شفع لأخيه شفاعة فأهدى له هدية فقد أتى باباً عظيماً من أبواب الربا فلا تأخذ عن شفاعتك مالاً، أما إذا كنت خدمتهم في شيء أعطوك المال عن خدمة أخذت لهم الجوازات تعبت لهم في الإقامة عملت أعمالاً كفيتهم إياها وأعطوك المال لخدمتك فقط، فلا حرج فلا نعلم حرجاً في ذلك في مقابل الخدمة التي خدمتهم إياها. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8198/حكم-اخذ-المال-عن-الشفاعة-في-المنافع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_301/30102.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":10534,"question":"تقول في الفقرة الأخيرة سماحة الشيخ: هل يجوز لنا أن نأكل مما يهديه لنا هذا الرجل من أكل وخضروات وغيره أم لا؟","title":"حكم قبول الهدية ممن يجمع الصلوات ويترك الجماعة","answer":"الجواب: الهدية لها شأن آخر، إذا كان مكسبه طيب لا بأس، الهدية تقبل حتى من الكافر إذا لم يكن هناك موجب لردها، الهدية أمرها أوسع، لكن إذا أراد ردها هجرًا له وتعزيرًا له من باب التنبيه على خطئه فإذا رد هديته وهجره حتى يتوب يكون هذا أصلح من باب التأديب، ومن باب الحث على إقام الصلاة وأدائها، فإذا لم يقبل هديته ولم يزره وهجره فهذا مشروع إذا كان فيه مصلحة، أما إذا كان قبولها والمجيء إليه أقرب إلى الصلاح وإلى أن يستفيد فلا بأس.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8709/حكم-قبول-الهدية-ممن-يجمع-الصلوات-ويترك-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_284/28406.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":10557,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من جمهورية مصر العربية، وباعثها أحد المستمعين من هناك هو: محمد عثمان، الأخ محمد له أكثر من سؤال، في سؤاله الأول يقول: إن جدي -رحمه الله- قسّم تركته قبل وفاته على والدي وعمي وعمتي، وهو عبارة عن أطيان زراعية، ولم يعط عمتي حقها الشرعي في تلك الأراضي، فما حكم الإسلام في ذلك؟ وماذا يجب عليّ فعله الآن، وما الحكم في المدة السابقة، وهي تزيد عن عشر سنوات؟","title":"العدل بين الأولاد في الوصية","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فلا ريب أن الواجب على جدك أن يعدل في الورثة والتقسيم، وأن يكون أولاده على قسمة الله: لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11]، في الهبة، وفي الإرث، ولقد ثبت عن رسول الله عليه الصلاة والسلام أنه قال لبشير بن سعد الأنصاري لما وهب ابنه النعمان غلاماً قال له ﷺ: أكل ولدٍ أعطيته مثل هذا؟، قال: لا، قال: اتقوا الله، واعدلوا بين أولادكم، فدل ذلك على أن يجب على الوالد العدل في عطيته لأولاده، فيكون لأبيك ولعمك أربعة أسهم، ولعمتك سهمين، هكذا يجب لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ، إن كانت عمتك سمحت لأخويها وهي مرشدة، سمحت لهم بحقها فلا حرج، وإلا فلها الحق في المطالبة في حقها لدى المحكمة، والله -جل وعلا- نسأله أن يوفق الجميع.\nالمقدم: اللهم آمين، جزاكم الله خيراً، المدة السابقة الحكم فيها لو تكرمتم؟\nالشيخ: هذا إلى المحكمة، إذا كانت ما سمحت العمة، فالمحكمة تنظر في الأمر في حقها، وفيما فات عليها في هذه المدة.\nالمقدم: يعني إن كان هناك محاصيل زراعية، أو ما أشبه؟\nالشيخ: كلها، تنظر المحكمة.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8731/العدل-بين-الاولاد-في-الوصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_322/32201.mp3","categories":["تربية الأولاد","الهبة والعطية"]},{"id":10602,"question":"المستمع عبيد بن حسين الإبراهيم سوري مقيم في عرعر بعث برسالة مطولة بعض الشيء يقول فيها: توفي ابن خالتي وقامت أمه بالتصدق لولدها، حيث أعطتني بقرة بصفة وقف لابنها أستفيد من لبنها على أن أطعم تلك البقرة وأعتني بها، وشاء الله أن البقرة ماتت حيث نطحت فذبحتها وبعت لحمها بمبلغ سبعة آلاف ليرة سوري، وصرفت تلك الفلوس حيث أنني محتاج لها، سؤالي: هل أشتري بقرة بدلاً منها وأعطيها للمتوفى كصدقة، أو أترك من بقرتي حيث أن لدي الآن بقرة أخرى أفيدوني جزاكم الله خيراً؟","title":"حكم من وضع عنده وقف فباعه مضطراً","answer":"الجواب: نعم، الواجب عليك أن تشتري بقرة مثلها حسب الطاقة، بالفلوس التي حصلت لك حين بعت البقرة بعد الذبح تصرفها في بقرة أخرى، تكون وقفاً وصدقة بدل التي ذبحت، وإذا كان عندك بقرة تناسب وعرضتها على اثنين من أهل المعرفة والخير ورأيا أنها مناسبة فلا بأس بالقيمة التي عندك، تكون وقفاً بدل البقرة التي ذبحت، وإذا اشتريت من غيرك بالسبعة الآلاف التي عندك بقرة أو زدت عليها من نفسك فهذا أحوط لك وأبعد عن التهمة، ويكون حكم البقرة الجديدة كالبقرة القديمة. نعم.","link":"https://binbaz.org.sa/fatwas/8788/حكم-من-وضع-عنده-وقف-فباعه-مضطرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_326/32615.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":10611,"question":"المستمع عبيد بن حسين الإبراهيم سوري مقيم في عرعر بعث برسالة مطولة بعض الشيء يقول فيها: توفي ابن خالتي وقامت أمه بالتصدق لولدها، حيث أعطتني بقرة بصفة وقف لابنها أستفيد من لبنها على أن أطعم تلك البقرة وأعتني بها، وشاء الله أن البقرة ماتت حيث نطحت فذبحتها وبعت لحمها بمبلغ سبعة آلاف ليرة سوري، وصرفت تلك الفلوس حيث أنني محتاج لها، سؤالي: هل أشتري بقرة بدلاً منها وأعطيها للمتوفى كصدقة، أو أترك من بقرتي حيث أن لدي الآن بقرة أخرى أفيدوني جزاكم الله خيراً؟","title":"حكم من وضع عنده وقف فباعه مضطراً","answer":"الجواب: نعم، الواجب عليك أن تشتري بقرة مثلها حسب الطاقة، بالفلوس التي حصلت لك حين بعت البقرة بعد الذبح تصرفها في بقرة أخرى، تكون وقفاً وصدقة بدل التي ذبحت، وإذا كان عندك بقرة تناسب وعرضتها على اثنين من أهل المعرفة والخير ورأيا أنها مناسبة فلا بأس بالقيمة التي عندك، تكون وقفاً بدل البقرة التي ذبحت، وإذا اشتريت من غيرك بالسبعة الآلاف التي عندك بقرة أو زدت عليها من نفسك فهذا أحوط لك وأبعد عن التهمة، ويكون حكم البقرة الجديدة كالبقرة القديمة. نعم.","link":"https://binbaz.org.sa/fatwas/8788/حكم-من-وضع-عنده-وقف-فباعه-مضطرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_326/32615.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":10818,"question":"رسالة وصلت إلى البرنامج من الرياض باعثها المستمع مسفر فهد سعيد القحطاني يقول: هناك عمارة من دورين اشتراها الوالد بمبلغ مائة وثلاثين ألف ريال، وتقبلت الصندوق العقاري بمبلغ مائة وثلاثة وعشرين ألف ومائتين وثمانية وتسعين، وهذا كان في حياة الوالد، وقد توفي قبل ثلاث سنوات، وقد أعطاني تلك العمارة، وأخبر إخواني الخمسة بذلك وأختين، وكان لديهم علم بذلك، ولم يعارض منهم أحد، وهو على قيد الحياة، حسب علمي، وأظن أن الوالد أعطاني العمارة حبًا لي، وليس تفضيلًا على إخواني وأخواتي، والآن أريد أن أبرئ ذمتي في هذا الموضوع، هل يجوز لي أن أمتلك تلك العمارة؟ مع العلم أنهم وقعوا على ورقة أنهم راضين بذلك، وليس لديهم مانع بعد وفاته؛ لأن العمارة باسم شخص ثاني، ولم تنقل ملكيتها، وهي مسجلة باسمي في الصندوق العقاري، وإنما أخشى أن يكون أحدهم غير راضٍ من قلبه، وهل يلحق والدي ذنب؟ أفتونا مأجورين، جزاكم الله خير الجزاء.","title":"حكم هبة الوالد شيئاً لأحد أولاده برضى البقية","answer":"الجواب:  إذا كان الواقع كما ذكرته فلا حرج، إذا كانوا مرشدين، ورضوا بذلك فلا حرج عليك، والحمد لله، وجزاهم الله خيرًا، القلوب إلى الله  ما دام صدقوا على ذلك، ورضوا بذلك، ولم يعارضوا فلا حرج عليك، إن شاء الله، نعم. المقدم: وفيما يخص والده؟ الشيخ: ولا حرج على والدك، ما دام سامحوه ورضوا، الحمد لله. نعم. المقدم: الحمد لله، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8992/حكم-هبة-الوالد-شيىا-لاحد-اولاده-برضى-البقية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_354/35403.mp3","categories":["تربية الأولاد","الهبة والعطية"]},{"id":10824,"question":"رسالة وصلت إلى البرنامج من الرياض باعثها المستمع مسفر فهد سعيد القحطاني يقول: هناك عمارة من دورين اشتراها الوالد بمبلغ مائة وثلاثين ألف ريال، وتقبلت الصندوق العقاري بمبلغ مائة وثلاثة وعشرين ألف ومائتين وثمانية وتسعين، وهذا كان في حياة الوالد، وقد توفي قبل ثلاث سنوات، وقد أعطاني تلك العمارة، وأخبر إخواني الخمسة بذلك وأختين، وكان لديهم علم بذلك، ولم يعارض منهم أحد، وهو على قيد الحياة، حسب علمي، وأظن أن الوالد أعطاني العمارة حبًا لي، وليس تفضيلًا على إخواني وأخواتي، والآن أريد أن أبرئ ذمتي في هذا الموضوع، هل يجوز لي أن أمتلك تلك العمارة؟ مع العلم أنهم وقعوا على ورقة أنهم راضين بذلك، وليس لديهم مانع بعد وفاته؛ لأن العمارة باسم شخص ثاني، ولم تنقل ملكيتها، وهي مسجلة باسمي في الصندوق العقاري، وإنما أخشى أن يكون أحدهم غير راضٍ من قلبه، وهل يلحق والدي ذنب؟ أفتونا مأجورين، جزاكم الله خير الجزاء.","title":"حكم هبة الوالد شيئاً لأحد أولاده برضى البقية","answer":"الجواب:  إذا كان الواقع كما ذكرته فلا حرج، إذا كانوا مرشدين، ورضوا بذلك فلا حرج عليك، والحمد لله، وجزاهم الله خيرًا، القلوب إلى الله  ما دام صدقوا على ذلك، ورضوا بذلك، ولم يعارضوا فلا حرج عليك، إن شاء الله، نعم. المقدم: وفيما يخص والده؟ الشيخ: ولا حرج على والدك، ما دام سامحوه ورضوا، الحمد لله. نعم. المقدم: الحمد لله، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8992/حكم-هبة-الوالد-شيىا-لاحد-اولاده-برضى-البقية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_354/35403.mp3","categories":["تربية الأولاد","الهبة والعطية"]},{"id":11244,"question":"هذا السائل -يا سماحة الشيخ- أيضًا يسأل في سؤاله الثاني ويقول: ما حكم الأب الذي لم يعدل بين أبنائه، ثم يكتب الأرض التي يملكها باسم زوجته حتى يحرم الابن الذي من زوجة أخرى من كل شيء، فما هي الحقوق التي على الابن الآخر المحروم تجاه والده، وبماذا تنصحون الأب مأجورين؟","title":"حكم الأب الذي لم يعدل بين أبنائه","answer":"الجواب: الواجب على الأب العدل بين الأولاد، كما قال النبي ﷺ: اتقوا الله واعدلوا بين أولادكم فالواجب عليه العدل بين الذكور والإناث في قسمة الميراث لا يخص أحدًا دون أحد، بل إذا أعطاهم أعطاهم جميعًا كالميراث، وإذا حرمهم حرمهم جميعًا، أما أن يخص أحدًا بعطية فلا يجوز، أو يتحيل ويعطي أمه وقصده للولد أو البنت فلا يجوز. أما إذا خص الزوجة بشيء ليس حيلة؛ تقديرًا لجهودها وأعمالها الطيبة فلا بأس، أما أن يفعل تحيلًا يكتب باسم الزوجة وهو قصده قد تواطأ معها على أنه للولد فهذا لا يجوز، الحيل التي تحرم ما أحل الله أو تحل ما حرم الله كلها باطلة، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/9425/حكم-الاب-الذي-لم-يعدل-بين-ابناىه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_291/29125.mp3","categories":["تربية الأولاد","الهبة والعطية"]},{"id":11279,"question":"في أحد أسئلته يقول: شخص له ثلاث زوجات، كل واحدة منهن لها أولاد ذكور وإناث وتختلف عن الزوجة الأخرى من جهة عدد الذكور والإناث، ويرغب الزوج قسمة العقارات عليهن بحيث يعطي كل واحدة منهن مسكنََا لها ولأولادها الذكور والإناث، علمًا بأن المساكن تختلف بعضها عن بعض من جهة القيمة والمساحة، فهل هذه القسمة مطابقة للشرع أم كيف توجهونه؟ جزاكم الله خيرًا.","title":"حكم من قسم بين أولاده المساكن مع اختلاف قيمتها","answer":"الجواب:  إن كانت القسمة للسكن فقط والعقار باقي على ملكه بحيث يقدر عليه بعد موته ويرثونه، هذا لا حرج يجتهد في التوزيع بينهم وفي إسكانهم والإنفاق عليهم، والعقار على ملكه يبقى على ملكه، وإذا مات حكمه حكم بقية العقار وإرث بين الجميع فلا بأس. أما إذا كان المقصود تمليكه فلابد من المساواة والعدل، يعطي الزوجات على السواء ويعطي الأولاد على السواء للذكر مثل حظ الأنثيين، يعطي الذكر مثل الأنثى مرتين، وكل زوجة يساويها بالأخرى حتى يعدل بينهن لأن الرسول ﷺ يقول: اتقوا الله واعدلوا بين أولادكم ويقول ﷺ: من كانت له زوجتان فمال إلى إحداهما جاء يوم القيامة وشقه مائل. فالحاصل: أن عليه العدل حسب الطاقة في زوجاته وفي أولاده إذا كان عطاء تمليك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9466/حكم-من-قسم-بين-اولاده-المساكن-مع-اختلاف-قيمتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_375/37517.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":11584,"question":"تسأل سماحتكم -جزاكم الله خيرًا- عن صديقة لها متوفىً زوجها تقول: إنها أحيانًا تأخذ منها بعض المال، ولكن تفكر في بعض الأوقات وتقول: أرجو أن لا أكون قد أخذت هذا المال بغير حقه؛ لأنه من مال أيتام، فبماذا توجهونها وذلكم الحال؟ جزاكم الله خيرًا.","title":"حكم أخذ المال من امرأة متوفى عنها زوجها","answer":"الجواب:  إذا كنت لا تعلمين؛ فلا حرج عليك، وعليك حسن الظن، والحذر من الوساوس، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9767/حكم-اخذ-المال-من-امراة-متوفى-عنها-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_386/38613.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":11597,"question":"بعد هذا رسالة بعثت بها إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (ن. م) تقول: يوجد عندي خماخم ذهب قد اشتريتها هدية لشغالة كانت عندي سابقًا، وعند سفرها نسيتها عندي، هل تنصحونني بإعطائها لخدامة أخرى، أم أتصرف فيها تصرفًا آخر؛ لأني أخشى إذا بعثتها إليها ألا تصل؟","title":"حكم من أهدى هدية ونسيها المهدى إليه عنده","answer":"الجواب:  الواجب بعثها إليها، إذا كنت أعطيته إياها، وتملكتها منك، ولكن نسيتها فهي ... كسائر مالها، الواجب عليك إيصالها إليها بالطريقة الممكنة، وليس لك التصرف فيها بإعطائها خدامة أخرى ولا غيرها، الواجب إيصالها إلى الخدامة التي أعطيتها إياها، ولا ترجعي في هبتك؛ يقول النبي ﷺ: الراجع في هبته كالراجع في قيئه. فالواجب إيصالها إليها بالطريقة الممكنة، أما إذا عجزت عن إيصالها إليها؛ فإنك تتصدقي بها عنها، إذا لم يتيسر إيصالها إليها؛ فإنه يتصدق بها عنها. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9788/حكم-من-اهدى-هدية-ونسيها-المهدى-اليه-عنده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_387/38714.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":11599,"question":"بعد هذا رسالة بعثت بها إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (ن. م) تقول: يوجد عندي خماخم ذهب قد اشتريتها هدية لشغالة كانت عندي سابقًا، وعند سفرها نسيتها عندي، هل تنصحونني بإعطائها لخدامة أخرى، أم أتصرف فيها تصرفًا آخر؛ لأني أخشى إذا بعثتها إليها ألا تصل؟","title":"حكم من أهدى هدية ونسيها المهدى إليه عنده","answer":"الجواب:  الواجب بعثها إليها، إذا كنت أعطيته إياها، وتملكتها منك، ولكن نسيتها فهي ... كسائر مالها، الواجب عليك إيصالها إليها بالطريقة الممكنة، وليس لك التصرف فيها بإعطائها خدامة أخرى ولا غيرها، الواجب إيصالها إلى الخدامة التي أعطيتها إياها، ولا ترجعي في هبتك؛ يقول النبي ﷺ: الراجع في هبته كالراجع في قيئه. فالواجب إيصالها إليها بالطريقة الممكنة، أما إذا عجزت عن إيصالها إليها؛ فإنك تتصدقي بها عنها، إذا لم يتيسر إيصالها إليها؛ فإنه يتصدق بها عنها. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9788/حكم-من-اهدى-هدية-ونسيها-المهدى-اليه-عنده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_387/38714.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":11640,"question":"امرأة توفيت سماحة الشيخ، وتركت قطعة أرض لمن يقرأ لها القرآن بعد وفاتها، فكيف التصرف في تلكم الأرض؟ ولا سيما وقد سمعنا أن قراءة القرآن، وإهداء ثوابها إلى الموتى غير جائزة، وهذا السؤال من المستمع: عيسى محمد سالم.","title":"حكم الوقف لقراءة القرآن على الواقف بعد موته","answer":"الجواب:  نعم غير مشروع قراءة القرآن للأموات، ولكن هذه الأرض تصرف غلتها في جماعة معلمي القرآن، تصرف غلتها للذين يعلمون القرآن، ولها أجرها العظيم، تعينهم.. في جماعة القرآن في البلد، أو في أي بلد، تصرف الغلة للقائمين بتعليم القرآن، حتى يستعينوا بها في أجور المدرسين، أو شراء الكتب، ونحو ذلك، أما أن يقرأ القرآن للميتة، لا. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9831/حكم-الوقف-لقراءة-القران-على-الواقف-بعد-موته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_389/38918.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":11647,"question":"من جدة رسالة بعث بها المستمع (ط. م. ر) يسأل ويقول: هل يجوز لوالدي أن يحرمني مما يترك لنا من أملاك، وغير ذلك؟ وهل يجوز له أن يكتب كل شيء باسم أخينا الأكبر؟ وما حكم الشرع في ذلك؟ جزاكم الله خيرًا.","title":"حكم حرمان الأب بعض أولاده من العطايا والميراث","answer":"الجواب:  ليس لوالدكم أن يظلمكم، بل يجب عليه أن يعدل في الحياة والموت، يقول النبي ﷺ: اتقوا الله، واعدلوا بين أولادكم فليس له أن يوصي لبعضكم دون بعض، وليس له أن يعطي بعضكم دون بعض في الحياة، بل يجب أن يترك ماله على شرع الله للجميع، وإن أوصى؛ فيوصي للجميع على حسب الميراث، لا يزيد ولا ينقص، بل على حسب الميراث، وإن أعطى في حياته؛ فعلى حسب الميراث، أما أن يخص بعضًا دون بعض؛ فهذا لا يجوز، بل هو منكر وظلم. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9834/حكم-حرمان-الاب-بعض-اولاده-من-العطايا-والميراث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_389/38921.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":11675,"question":"تقول أيضًا في سؤال آخر: شخص أهدى إلى والدته هدية من ذهب، ومع مرور الزمن احتاج هذه الهدية، فأخذها من والدته، فما الحكم؟","title":"حكم من أهدى لوالدته ذهباً ثم أخذه منها لحاجته إليه","answer":"الجواب:  إذا رضيت والدته وأعطته الهدية، وليس له إخوان، أو له إخوان رضوا، إخوان مكلفون مرشدون ورضوا؛ لا بأس، أما إذا كان له إخوان صغار، أو لم يرضوا؛ فليس له أن يأخذها، بل تكون للجميع، لأن الرسول ﷺ يقول: اتقوا الله، واعدلوا بين أولادكم؛ لأنها ملكتها، فليس له أن يأخذها وحده، بل عليها أن توزع الهدية بينه وبين إخوته، إلا أن يسمحوا إذا كانوا مرشدين، فلا بأس إذا سمحوا، وإلا فعليها أن تمسك لا تعيدها إليه. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9858/حكم-من-اهدى-لوالدته-ذهبا-ثم-اخذه-منها-لحاجته-اليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_390/39007.mp3","categories":["تربية الأولاد","الهبة والعطية"]},{"id":12556,"question":"رسالة وصلت إلى البرنامج من المستمع (م. ص. ع) يقول في رسالته: دخلت أحد المساجد ومعي مصحف، ورأيت في المسجد مصاحف ذات طباعة واضحة، وقمت باستبدال مصحفي بواحد من تلك المصاحف الموجودة في المسجد، هل يحق لي ذلك، أم لا؟","title":"حكم استبدال مصحف أوقف على مسجد بمصحف آخر","answer":"الجواب:  ليس لأحد أن يأخذ من أوقاف المسجد شيئًا، لا من المصاحف، ولا من غيرها، إلا إذا كانت موضوعة للتوزيع، إذا كان وضعها الواضع للتوزيع؛ فلا بأس بذلك، إذا قال له الإمام أو المؤذن: هذه للتوزيع؛ فلا بأس، أما إذا كان وضعت لينتفع بها المصلون، والقراء في المسجد؛ فليس لأحد أن يأخذ منها شيئًا، ولا أن يضع بدلها ما هو دونها، نعم. المقدم: نذكر التعليل لو تكرمتم؟ الشيخ: لأنها وقف، لأنها وقف على القراء في المسجد. المقدم: هذه ناحية. الشيخ: ولأن وجود ما هو أصلح ينبغي أن يبقى للقارئ الذي أراده الموقف، فلا يأخذ الطيب، ويدع ما هو دونه، يبقى الطيب لأهل المسجد. المقدم: وحتى لا يخلو المسجد. الشيخ: وكذلك هذا منه حتى لا يخلو من المصاحف أيضًا، لكن قد يقول: أنا وضعت مصحفي بدل المصحف. المقدم: لا، قصدي حتى لا يخلو المسجد من المصاحف ذات الطباعة الجيدة. الشيخ: نعم هذا مطلوب. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10756/حكم-استبدال-مصحف-اوقف-على-مسجد-بمصحف-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_410/41002.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":12679,"question":"المستمع: أحمد محمد مصري مقيم في جدة بعث برسالة مطولة بعض الشيء يقول فيها: لي أخت تزوجت من رجل، ثم طلقت منه بعد أن أنجبت منه بنتين، وتزوجت برجل آخر وهي تعمل، ويدخل راتبها البيت، وقد تمكنت من بناء شقة هي وأختها، وزوجها يعلم بذلك، وبعد أن انتهت من بناء هذه الشقة، فإن زوجها يطلب منها أن تكتب ما تمتلكه من هذه الشقة لابنتها التي أنجبتها منه، وحرمان ابنتيها من زوجها الأول، مع العلم أنها بنت هذه الشقة من مالها الذي كانت تعمل وتحصل عليه، وجهونا حول هذا الموضوع، جزاكم الله خيرًا؟","title":"حكم تخصيص أحد الأبناء بهبة دون غيره","answer":"الجواب:  لا يجوز لهذا الرجل أن يلزمها بذلك، ولا أن يأمرها بذلك، ولا يجوز لها أن تطيعه في ذلك؛ لأن هذا من الظلم، والرسول -عليه الصلاة والسلام- يقول: اتقوا الله، و اعدلوا بين أولادكم. فالواجب عليها أن تعدل بين بناتها، وأن يكن سواء في وصيتها وعطيتها، وليس لها أن تحيف فتزيد واحدة على أخرى، وليس له أن يأمرها بذلك، بل هذا حرام عليه، وهو من الإعانة على الإثم والعدوان، ومن الأمر بالظلم فلا يجوز، فليس لها طاعته في هذا الأمر، بل هذه معصية، والرسول  يقول: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق ولو أوصت، أو أعطت البنت التي هي بنته دون البنتين؛ فالعطية باطلة، والوصية باطلة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10889/حكم-تخصيص-احد-الابناء-بهبة-دون-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_417/41708.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":12808,"question":"المستمع محمد علي محمد عسيري بعث برسالة مطولة ملخص ما فيها طلب إيضاح أحكام الوقف، وهل يجوز بيعه إذا تعطلت منافعه، ونقله إلى مصالح أخرى، جزاكم الله خيرًا؟","title":"حكم بيع الوقف عند تعطل منافعه","answer":"الجواب:  نعم الوقف لا يباع ولا يوهب ولا يورث كما قاله النبي ﷺ: تصدق بأصلها قال لعمر تصدق بأصلها، لا يباع ولا يوهب، ولكن ينفق وثمره فالوقف لا يباع ولا يوهب ولا يورث، بل يبقى حبسًا تنفق غلته وثمرته في الوجوه التي عين، وجوه الخير التي عينها الواقف، وإذا تعطلت منافعه؛ فإنه يباع، ولا يترك، يباع ويرجع ثمنه فيما هو أصلح منه إذا تعطلت المنافع، لكن من طريق المحكمة، إذا كانت البلاد فيها محكمة؛ تراجع المحكمة حتى تضبط الأمور. أما إذا كان في بلاد ما فيها محكمة؛ فالولي يقوم بذلك، وكيل الوقف يبيعه، ويشتري به ما هو أصلح، إن كان بيتًا؛ اشترى بيتًا أصلح، ولو صغيرًا، أو دكانًا ولو صغيرًا حسب التيسير، يجتهد في تحصيل ما هو أصلح ولا يترك معطلًا؛ لأن هذا من إضاعة المال، والرسول ﷺ نهى عن إضاعة المال، فإذا تعطلت منافع الوقف؛ فإنه يباع، ويشترى به ما هو أصلح من بيت، أو دكان، أو مزرعة، أو نحو ذلك، تنفق ثمرته في الوقف الذي بيع ثمرته مثلما في غلة الوقف الذي بيع حسب الوصية، وحسب وثيقة الوقف. أما إذا كان في بلد فيها محاكم شرعية؛ فإن الوكيل يراجع المحاكم، ويرى ما توجهه إليه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11022/حكم-بيع-الوقف-عند-تعطل-منافعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_462/46213.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":12920,"question":"من المستمع حسن سعيد محمد القعيدي من اليمن حضرموت رسالة ضمنها أكثر من سؤال، في سؤال له طويل ملخصه يقول: إذا انقطعت منافع الوقف فهل يباع لينتفع بثمنه في جهة أخرى؟","title":"حكم بيع الوقف إذا تعطلت منافعه","answer":"الجواب:  نعم، إذا تعطلت منافع الوقف؛ يباع ويشترى به ما هو أصلح منه، فإذا كان بيتًا تعطل، أو دكانًا تعطل؛ يباع، ويشترى به بيت أصغر، أو دكان أصغر ينتفع به، أو أرضًا تعطلت من الزراعة، ما رغب فيها الناس؛ تباع حتى تتخذ مساكن، ويشترى بها ما هو أصلح منها، أو يعمرها صاحب الوقف بيوتًا للسكن، إذا كان يستطيع ذلك، ولا تعطل؛ لا يترك الوقف عاطلًا؛ لأن هذا من باب إضاعة المال، لا يجوز، بل يجب أن ينظر في أمره، إما بإصلاحه، وتعميره، وإما ببيعه وشراء ما هو أصلح منه، ويكون ذلك بواسطة المحكمة، إذا كان في البلاد محكمة، في بلاد إسلامية فيها محكمة، وإلا يكون ذلك بواسطة أهل الخير، كمركز إسلامي، أو العالم الذي يوثق به في البلد، أو في الأقلية الإسلامية؛ حتى يتعاون مع ناظر الوقف في ذلك. المقصود: أن ناظر الوقف يتعاون مع أهل الخير في ذلك حتى يبرئ ذمته، وحتى يسلم هذا الوقف من التعطل. أما إذا كان في بلد فيها محكمة؛ فإن الناظر يستشير المحكمة، ويسير على ضوء توجيهات المحكمة في البيع، وفي شراء البديل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11135/حكم-بيع-الوقف-اذا-تعطلت-منافعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_469/46905.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":12933,"question":"هذه رسالة وصلت من المغرب، من أحد الإخوة المستمعين، يقول في هذا  شخص أهديت له هدية عبارة عن مجوهرات ذهبية،  هل له أن يبيعها، ويستفيد بثمنها؟ أفتونا جزاكم الله خيرًا.","title":"حكم بيع أو إهداء الهدية","answer":"الجواب:  نعم، إذا أهدي لك هدية، وليست رشوة، هدية من أخ محب، أو من قريب ليست في مقابل خيانة ولا .. فلا بأس، تكون مالًا لك تتصرف فيها .. تبيعها .. تمسكها .. تهديها إلى غيرك، لا بأس، أما إن كانت رشوة حتى تميل عن الحق، أو حتى تحكم بالجور، أو حتى تظلم أحدًا؛ فلا يجوز ذلك، إذا كانت هذه الهدية رشوة لك حتى تظلم، أو تخون في قضية عندك، أو أنت قاضي وتحكم بغير الحق، كل هذا منكر. وأما إذا كان هدية لله وفي الله؛ لأنك صديقه؛ لأنك أخوه في الله؛ لأنك قريبه؛ ليس لأي أمر آخر من أمور الخيانات والظلم؛ فلا بأس بذلك، هي مال لك تتصرف فيها، والسنة لك أن تقابله، أن تثيبه على هديته، كان النبي ﷺ يقبل الهدية، ويثيب عليها، يعني: يعطي عليها المقابل، هذا هو الأفضل. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11149/حكم-بيع-او-اهداء-الهدية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_501/50108.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":12961,"question":"السائل من القصيم يقول: هل إهداء المصحف جائز إذا كان قد أتاني هدية لست بحاجة إليه لوجود آخر عندي، فهل إهداء المصحف جائز؟","title":"حكم إهداء المصحف","answer":"الجواب:  نعم، إلى المسلم تعطيه المسلم، تهديه إلى أحد المسلمين طيب. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11178/حكم-اهداء-المصحف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50217.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":13073,"question":"هذا السائل حمدي يعمل بالرياض يقول: بأنه يعمل بالمملكة، فهل عند عودتي لبلدي لا بد من أخذ هدايا للأهل والأقارب، علمًا بأن ذلك الموضوع سوف يكلفني الكثير، وهل إذا لم آخذ هدايا أكون قد ارتكبت إثمًا من باب قطيعة الرحم لأهلي، وجهونا في ذلك؟","title":"حكم بذل الهدية","answer":"الجواب:  الهدايا غير واجبة، لا، ما هو بلازم، الهدايا غير واجبة، ولا تكون قاطعًا للرحم إذا ما حملت هدايا، الهدايا باختيارك إن رأيت أن تأخذ هدايا لخواص أقاربك؛ فلا بأس، وإلا ليس بلازم، أنت أعلم بالمصلحة، المهم أن تحفظ المال لحاجة البيت، وحاجتك، وحاجة أهلك، فإذا اشتريت هدية خفيفة للزوجة، أو لأبيك، أو لأمك، أو لإخوانك؛ فلا بأس، وإن شق عليك ذلك؛ فالحمد لله، ما لزوم هدية، المال احفظه لحاجة البيت، لحاجتك، أو لقضاء دينك، أما الهدايا فهي مستحبة عند اليسر .. عند القدرة واليسر إذا أهديت لإخوانك، الرسول ﷺ يقول: تهادوا تحابوا اللهم صل عليه وسلم، فالهدية طيبة مع القدرة، ومع السعة إذا تيسرت من غير تكلف. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11289/حكم-بذل-الهدية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_507/50705.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":13078,"question":"هذه سائلة تقول في هذا  عندي مبلغ من المال، وأريد أن أجعله وقفًا في سبيل الله  و أي الأعمال أفضل في هذا الوقف، هل هو بناء مسجد، أم غيره أفضل، دلوني يا سماحة الشيخ مأجورين؟","title":"أفضل أنواع الوقف","answer":"الجواب:  إذا كان المال كثيرًا فاجعليه في عقار... في وجوه الخير، بناء المساجد، والصدقة على الفقراء والمساكين، ومساعدة طلبة العلم في طلب العلم، مساعدة من يقوم بعمل شرعي، ويعجز عنه. المقصود: أن يكون في أعمال البر، إذا كان مالًا كثيرًا، يشترى به عقارًا كبيرًا، أو عقارات توقف في أعمال البر، ووجوه الخير، من الصدقة على الفقراء والمساكين .. من مساعدة المجاهدين في سبيل الله .. من بناء المساجد إلى غير هذا من وجوه الخير، الصدقة على الأقارب المحاويج، إلى غير ذلك. أما إن كان قليلًا فاصرفيه في الصدقة على الفقراء إذا كان في أقارب فقراء؛ فأعطيهم إياه، فإن كان ما هناك أحد؛ يصرف في تعمير المساجد، أو في الفقراء في غير البلد إذا كان ما في البلد فقراء بلدك. المقصود: أنه يكون في وجوه البر، لكن إذا كان قليلًا؛ تجعلينه في الفقراء، أو في تعمير المساجد مساهمة، كله طيب. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11295/افضل-انواع-الوقف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_507/50710.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":13231,"question":"السائلة من اليمن تقول: لي جارة ملتزمة بشرع الله، والحمد لله، ولكن زوجها شارب للخمر، وهناك شبهة في بيعه للخمر، ما حكم الأكل الذي تهديه لي هذه الجارة، هل أقوم بأكله أم لا، وهل أقبل ما تهديه إلي من هدايا؛ علمًا بأنها تدعوه إلى الله؛ فلا يجيب، وجهونا بذلك؟","title":"حكم قبول الهدايا ممن اختلط ماله بالمال الحرام","answer":"الجواب:  لا حرج في ذلك إذا كان سامحًا لها تهديه، إذا كان سامحًا لها تهديه من ماله؛ فلا بأس؛ لأن المال المختلط يجوز أخذه، والنبي ﷺ أكل من طعام أهل الكتاب، واشترى منهم، وهم يأكلون الربا، ومع هذا اشترى منهم طعامًا، وأكل من طعامهم؛ فدل ذلك على أن المال المختلط الذي فيه ربا، أو فيه ثمن خمر، أو ما أشبه ذلك، وعندهم أموال أخرى حلال لا بأس، الأصل الحل والإباحة حتى تعلم أن هذا المال ربا أو هذا المال من ثمن الخمر، فلا، إذا علمت أن هذا الطعام اشتراه من ثمن الخمر، أو اشتراه من الربا فلا يجوز، وأما إذا لم تعلم؛ فالأصل الإباحة والحل. ولكن هذا الزوج ينبغي لها أن تبتعد عنه مهما أمكن، وإن كان مسلمًا لكن كونه يعتاد شرب الخمر؛ هذه معصية عظيمة، وفسق ظاهر، فكونها تطلب الطلاق منه وتعافه خير لها وأولى لها، وخير لذريتها أيضًا، نسأل الله العافية والسلامة. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11512/حكم-قبول-الهدايا-ممن-اختلط-ماله-بالمال-الحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_520/52014.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":13273,"question":"السائل يقول: هل تقبل هدية من مشرك؟","title":"حكم قبول الهدية من المشرك","answer":"الجواب: هذا فيه تفصيل: إذا كانت الهدية لا تتضمن شرًا على مسلم، لا يتسلط بها الكافر عليه، أو لا يتجرأ بها على المسلمين، ولا يترتب عليها شر؛ فإنه يقبلها المسلم، ويكافئ عليها، يكافئ عليها مثلها، أو أحسن منها، والنبي ﷺ قبل من قوم، ورد على قوم، قبل من مشركين بعض الهدايا، ورد على آخرين، لم يقبل هداياهم. فإذا كان قبولها أصلح، يترتب عليها تأليف قلبه، ومحبته للمسلمين، ويثيب عليها أكثر من المهدى إليه؛ قبلها، فإن كان قبولها يسبب شرًا على المسلمين، أو أن هذا المهدي يتجرأ على المسلمين، أو يؤذيهم، أو يفعل أشياء تضرهم بسبب هذه الهدية، أو المُهدَى إليه هذه الهدية تفضي إلى محبته للكافر المُهدِي، والتعاون معه فيما يضر المسلمين؛ لم يقبلها؛ لئلا تضره؛ لئلا تجره إلى الباطل. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11557/حكم-قبول-الهدية-من-المشرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_509/50910.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":13379,"question":"تقول: شخص ترك ثلاثة من الأولاد، ولد وبنتين، وترك الإرث للولد، وتوفي هذا الولد، وواحدة من البنات، وواحدة ما تزال على قيد الحياة، فهل يحق لها أن تطالب ابن أخيها المتوفى؟","title":"هل للأنثى أن تطالب بحقها من الميراث؟","answer":"الجواب: نعم، هذا جور جعله المال للذكر، وإلا للأنثيين، هذا جور، ولا مانع من مطالبة البنتين لأخيهم بحقهما، أو لابنه بعد موته بحقهما، ورثة الميتة، والحية تطالب بحقها، إلا أن يكون له مسوغ شرعي، يعني: يعتقد أنهما كافرتان، ليس لهما إرث منه، فهذا يرجع إلى للمحكمة، تراجع المحكمة في ذلك. أما إذا كان الولد مسلمًا، والبنتان مسلمتين، والميت مسلم، فالواجب أن تكون التركة بين الجميع بين الذكر والأنثى.. لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11] تقسم بينهما، للرجل نصفها، وللبنتين نصفها، الثاني بينهما، فإذا كان في ذلك إشكال، أو نزاع؛ فهذا يرجع فيه إلى المحكمة الشرعية. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11669/هل-للانثى-ان-تطالب-بحقها-من-الميراث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_477/47704.mp3","categories":["الفرائض","الهبة والعطية","نصائح وتوجيهات"]},{"id":13419,"question":"قبول الصيدلي هدايا من الشركات المنتجة لبعض الأدوية، رغم أنه ليس صاحب المال الذي يعمل به، وإنما يعمل بالأجر فيه، وأن هذه الهدايا لن تؤثر على عملية البيع والشراء لمنتجات هذه الشركات التي قدمت الهدايا في الصيدلية التي يعمل بها هذا الصيدلي، وماذا لو أثرت هذه الهدايا على عملية البيع والشراء لمنتجات هذه الشركات في هذه الصيدلية؟","title":"حكم قبول العامل هدية من عملائه","answer":"الجواب: هذا أيضًا فيه تفصيل: إذا كانت الهدايا تسبب له خيانة في العمل، وإيثارًا هذه الشركة على غيرها، فيجتهد في بيع منتجاتها، وما يكون لها عنده، ويتساهل مع الباقين، فليس له ذلك، هو مؤتمن على بيع الجميع الذي عنده، وهو عامل، مأمور بأن يبيع ما عنده من هذه الأدوية، أو هذه السلع. فإذا كانت الهدية لا تعلق لها بذلك، بل أهدوا إليه؛ لأنه قريبهم، أو يعينهم على أشياء، أو لأنه وكيلهم، وهي لا تؤثر عليه في أعماله، ما نعلم ما يمنع من قبولها، أما إن كانت تؤثر في العمل، وتجعله يميز هذه الشركة، فيحرص على بيع منتوجها، وما توكله عليه، ويتساهل في أمر الباقين.. فهذا لا يجوز؛ لأن فيه خيانة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11716/حكم-قبول-العامل-هدية-من-عملاىه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_477/47710.mp3","categories":["الهبة والعطية","أحكام الموظفين"]},{"id":13531,"question":"آخر أسئلة في رسالة هذه السائلة سماحة الشيخ تقول السائلة: والدي متزوج من امرأتين، فجدي لأبي قبل أن يتوفاه الله أوصى ببيت لنا، وبيت لإخواني من أبي، فهل يجوز لوالدي أن يتصرف في البيت الذي هو ملكنا بأن يغير في بناياته، مع العلم أنه يغيره إلى الأحسن؛ لأن أحد إخواني قد عارض ذلك وقال: لا يجوز لوالدي أن يتصرف في ملكنا؟ وجهونا في ضوء هذا السؤال.","title":"وجوب العدل بين الأبناء","answer":"الجواب: لا مانع، يتصرف بتحسين ما يخصكم، لكن بشرط أن يعطي إخوانكم مثله، لابد من العدل؛ لأن الرسول ﷺ يقول: اتقوا الله واعدلوا بين أولادكم فإذا كان بيتكم يحتاج إلى ألف ريال، ألفين، ثلاثة؛ فلابد يعطي إخوانكم من أبيكم مثل ذلك؛ لأن عليه أن يعدل بينكم، وإلا فلا يجوز له يخصكم بشيء في إصلاح بيتكم، ولا يعطي إخوانكم إلا برضاهم إذا كانوا مرشدين ورضوا، أما إذا كانوا مرشدين ولم يرضوا؛ فليس له أن يخصكم بشيء، لا من جهة إصلاح البيت، ولا من جهة غيره، لابد من العدل. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11855/وجوب-العدل-بين-الابناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_532/53203.mp3","categories":["تربية الأولاد","الهبة والعطية"]},{"id":13872,"question":"هذا السائل يقول الذي رمز لاسمه بـ (أ . أ) يقول: كيف يكون العدل بين الأولاد وخاصة بأنني متزوج من زوجتين؟","title":"كيفية العدل بين أولاد الزوجات","answer":"الجواب: كل جماعة يعطون حقوقهم، العدل فيهم أن تعطيهم حقوقهم، فالاثنان لهم شيء والثلاثة لهم شيء والأربعة لهم شيء، فإذا كان أولاد الزوجة إحدى الزوجات اثنين، وأولاد الأخرى ثلاثة أربعة كل يعطى حقه، كل يعطى حقه، وهكذا الزوجة الثالثة والرابعة تعطيهم النفقة اللازمة.\nأما العطايا التي غير النفقة فلابد من العدل فيها، تعطيهم شيء زائد على النفقة لابد من العدل؛ لقول النبي ﷺ: اتقوا الله واعدلوا بين أولادكم أما النفقة فعلى حسب الحاجة الأولاد الكثير لهم نفقة والقليل لهم نفقة، والصغير له نفقة والكبير له نفقة، يختلفون في كسوتهم وفي غير ذلك، نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12292/كيفية-العدل-بين-اولاد-الزوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50620.mp3","categories":["النفقات","الهبة والعطية","تربية الأولاد"]},{"id":13886,"question":"هذا السائل يقول الذي رمز لاسمه بـ (أ . أ) يقول: كيف يكون العدل بين الأولاد وخاصة بأنني متزوج من زوجتين؟","title":"كيفية العدل بين أولاد الزوجات","answer":"الجواب: كل جماعة يعطون حقوقهم، العدل فيهم أن تعطيهم حقوقهم، فالاثنان لهم شيء والثلاثة لهم شيء والأربعة لهم شيء، فإذا كان أولاد الزوجة إحدى الزوجات اثنين، وأولاد الأخرى ثلاثة أربعة كل يعطى حقه، كل يعطى حقه، وهكذا الزوجة الثالثة والرابعة تعطيهم النفقة اللازمة.\nأما العطايا التي غير النفقة فلابد من العدل فيها، تعطيهم شيء زائد على النفقة لابد من العدل؛ لقول النبي ﷺ: اتقوا الله واعدلوا بين أولادكم أما النفقة فعلى حسب الحاجة الأولاد الكثير لهم نفقة والقليل لهم نفقة، والصغير له نفقة والكبير له نفقة، يختلفون في كسوتهم وفي غير ذلك، نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12292/كيفية-العدل-بين-اولاد-الزوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50620.mp3","categories":["النفقات","الهبة والعطية","تربية الأولاد"]},{"id":13960,"question":"تسأل أختنا وتقول: هل يجوز أن أخص أولادي الذكور ببعض أثاث المنزل والأجهزة، مثل: الثلاجات والمسجلات والأشياء المعمرة..الشيخ: أعد أعد!!المقدم: تقول: هل يجوز أن أخص أولادي الذكور ببعض أثاث المنزل والأجهزة، مثل: الثلاجات والمسجلات والأشياء المعمرة؛ كي تكون ملكًا لهم بعد وفاتي؛ لأن البنات سبق وأن جهزتهن، هل هذا جائز أو لا؟","title":"حكم تخصيص الذكور بشيء دون الإناث","answer":"الجواب: ليس لك ولا لغيرك تخصيص الذكور بشيء دون البنات، بل الواجب التعديل بين الجميع؛ لقول النبي ﷺ: اتقوا الله واعدلوا بين أولادكم، فلا يجوز لك أن توصي للبنين بشيء دون البنات، إلا إذا كن رشيدات ورضين بذلك؛ فلا حرج في ذلك، والأحوط عدم الوصية للبنين ولو رضي البنات؛ لأنهن قد يرضين حياء منك، وهن في الحقيقة لا يرضين بذلك، فالأحوط لك أن لا تخصي البنين بشيء أبدًا، حتى ولو فرضنا أن البنات رضين بذلك، لأني أخشى أن يرضين بذلك مكرهات أو مستحيات، بل اجعلي ما خلفك للجميع على قسمة الله : لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11]. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12381/حكم-تخصيص-الذكور-بشيء-دون-الاناث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_605/60505.mp3","categories":["تربية الأولاد","الهبة والعطية"]},{"id":13992,"question":"هذا السائل ناصر إبراهيم من حوطة بني تميم، يقول في هذا  حصل وأن قمت ببيع بيت صغير مبني من الطين، وبعد البيع عثرت الوالدة على وثيقة لهذا البيت ووجد فيها وقف في أضحية من ريعه دون علمي ولم يدخل علي من هذا البيت شيء من إيجاره، والمبلغ المبيوع بهذا البيت هو خمسة آلاف ريال منذ أكثر من عشر سنوات، فهل يسقط البيع شرعًا في هذه الحالة، أم يلزمني نقل الوقف ويبقى في ذمتي سماحة الشيخ؟","title":"حكم من باع شيئًا وتبين أنه وقف","answer":"الجواب: عليك مراجعة المحكمة في إبطال البيع وبقاء الوقف على حاله، وعرض الوثيقة على القاضي والقاضي ينظر في الأمر، فإن لم يتيسر رد البيع فالثمن يجعل في وقف آخر الذي دخل عليك يكون في وقف آخر، يكون في نخلة تقع وقفًا له، يكون في أواني تكون وقفًا له تستعمل ينتفع بها، المقصود: الثمن تجعله في شيء ينفع الميت نخلة أو نخلتين ينتفع بثمرها أو غير ذلك مما ينفع الميت، حسب التيسير. نعم.\nالمقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/12407/حكم-من-باع-شيىا-وتبين-انه-وقف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_539/53916.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":14065,"question":"المستمع أنيس يحيى من مدينة الدوادمي بعث يسأل ويشكو من سوء معاملة أبيه، فهو يقول: إن له أخًا أكبر منه، وقد زوجه أبوه وأعطاه سيارة لكنه لم يفعل به مثل ما فعل بأخيه رغم نصح الناس له، ثم إنه أعطاه قطعة أرض فتصرف فيها وباعها، وسلم الثمن للوالد، ثم طلب والده ثمن تلك الأرض فأبى أن يعطيه، ويسأل سماحة الشيخ كيف يتصرف؟ وهل إذا ذهب إلى المحكمة هل يكون آثمًا؟ وجهوه ووجهوا والده جزاكم الله خيرًا.","title":"ما حكم عطية بعض الأولاد دون الآخرين؟","answer":"الجواب: الواجب على الوالد أن يعدل، ولا يجوز أن يخص بعض الأولاد بعطية أو زيادة على بقية الأولاد هذا لا يجوز؛ لأن الرسول عليه السلام قال: اتقوا الله واعدلوا بين أولادكم، هذا كلام المصطفى عليه الصلاة والسلام، اتقوا الله واعدلوا بين أولادكم، ولما جاءه بشير بن سعد الأنصاري  وذكر له أنه أعطى ابنه النعمان غلامًا، قال له النبي ﷺ: أعطيت ولدك كلهم مثله؟ ، قال: لا، قال: رده، اتقوا الله واعدلوا بين أولادكم، فليس له أن يعطي بعضهم سيارة أو مالًا أو أرضًا ولا يعطي الآخرين لا، بل إما أن يسوي بينهم في العطاء وإما أن يرجع في عطيته، هذا هو الواجب عليه. وأنت أيها الولد! لو توسطت بعض الطيبين من الأقارب أو غيرهم حتى يصلحوا بينك وبين الوالد يكون هذا حسنًا إن شاء الله، أحسن من الذهاب إلى المحكمة، إن تيسر من يشير على والدك وينصحه حتى يلتزم بالحق، وحتى يعدل فهذا حسن، وهذا أولى من المخاصمة، فإن أبى فلك أن تخاصمه إلى المحكمة، لك أن تخاصمه لأجل أنه قد ظلم، ولا بد من تعديل من جار عن الطريق، لا بد أن يعدل ويلزم بالحق من طريق المحكمة، وإن سمحت أنت ولم تخاصمه فأنت مأجور، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12487/ما-حكم-عطية-بعض-الاولاد-دون-الاخرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48406.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية"]},{"id":14108,"question":"هل يجوز أخذ أي كتاب سواء كان قرآن أو أي كتاب آخر كتب عليه وقف، هل يجوز أخذه من المسجد؟","title":"حكم أخذ كتاب أو مصحف موقوف في مسجد","answer":"الجواب: لا يجوز أخذه من المسجد، بل يترك في المسجد لينتفع به من كان في المسجد من القراء، يطالعون فيه يستفيدون منه؛ لأن الواضع الذي وضعه في المسجد أو في مكتبة المسجد قصده نفع الناس، فلا تأخذ المصحف الذي في المسجد ولا الكتاب الذي في المسجد، دعه للقراء في المسجد أو في المكتبة التي في المسجد.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12548/حكم-اخذ-كتاب-او-مصحف-موقوف-في-مسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48416.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":14232,"question":"المستمع (م. م) من قطر بعث يسأل ويقول: هناك بعض أناس يأتون بمصاحف قديمة ويضعونها في المساجد ويستبدلونها بمصاحف جديدة من نفس المسجد فهل هذا جائز؟","title":"حكم استبدال المصاحف من المسجد واستعارتها","answer":"الجواب: ليس لأحد أن يأخذ من مصاحف المسجد شيء، المصاحف التي في المسجد يجب أن تبقى في المساجد وليس لأحد أن يأخذ منها شيئًا أو يبدلها، بل الواجب تركها في المساجد؛ لأن أهلها أرادوا أنها وقف لينتفع بها المسلمون في المسجد، فليس لأحد أن يأخذ منها شيئًا ولا أن يبدلها لا بقديم ولا بجديد.\nالمقدم: هل الاستعارة من المساجد جائزة أو لا؟\nالشيخ: ليس له أن يستعير، أما من المكتبات لا بأس إذا سمح مدير المكتبة والقائم عليها بالإعارة لا بأس، أما ما وضع في المسجد من الكتب أو من المصاحف فلا يستعار بل يطالعه وهو في المسجد. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12691/حكم-استبدال-المصاحف-من-المسجد-واستعارتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_486/48606.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":14564,"question":"سماحة الشيخ، بعض الآباء في المعاملة يميلون إلى البعض دون الآخرين، ويفرقون بينهم، هل من توجيه للآباء حول ذلك؟","title":"توجيه للأباء الذين لا يعدلون بين أولادهم","answer":"الجواب: الواجب على الآباء والأمهات تقوى الله في أولادهم، والعدل بينهم في النصيحة والتوجيه والإرشاد والتعليم؛ لأنهم جميعًا في الذمة أمانة، فيجب على الوالدين أن يتقوا الله في أولادهم، وأن يجتهدوا في تربيتهم التربية الإسلامية، وأن يحرصوا على الجد في الإحسان إليهم جميعًا، وعدم التخصيص؛ لأنهم جميعًا في الذمة.  فالواجب العناية بهم جميعًا، والحرص على تربيتهم التربية الإسلامية، وإذا كانوا محاويج جميعًا وجب الإنفاق عليهم بحسب حاجتهم إذا كان والدهم قادرًا على ذلك. أما أن يخص بعضهم من غير موجب شرعي، بل بالهوى فلا يجوز، فالواجب تقوى الله والعدل، كما قال النبي ﷺ: اتقوا الله، واعدلوا بين أولادكم. فعلى الأب وعلى الأم العدل، وتحري الحق في تربية الأولاد، والإنفاق على الأولاد وغير ذلك، لكن من عصى الله من الأولاد وعق والديه لا يكون له حق مثل حق من أطاع وبر بوالديه، من عصى والديه وعقهم فهو يستحق العقوبة والتأديب، وليس له حق مثل حق من أطاع وبر، فالعاق يؤدب ويعامل بما يستحق حتى يدع العقوق، وحتى يستقيم على بر والديه، ولا يكون له من الحق مثل حق من بر والديه، واستقام على طاعة الله فيهما. وهكذا من كان غنيًا ليس له حق فيما يعطاه الفقير، إذا كان أحد الأولاد فقيرًا أو مريضًا ليس عنده قدرة على الكسب، وأبوه يستطيع فإنه ينفق عليه، وليس للغني حق في ذلك، بل هذا من أجل الحاجة، فالأب ينفق على ولده الفقير والأم كذلك، ولا يكون جائرًا ولا ظالمًا إذا أنفق على الفقير، وعالج المريض؛ لأنه لا يستطيع، وترك القادر الذي يستطيع عنده المال ينفق على نفسه، ويعالج نفسه فهو مستغن عن والديه بما أعطاه الله من المال. أما الفقير كالطفل والمريض الذي ليس عنده ما يعالج به ونحو ذلك ممن يعجز عن النفقة لفقره أو مرضه أو علة به أو نحو ذلك ليس مثل الصحيح الغني، والله -جل وعلا- يقول سبحانه في كتابه العظيم: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ويقول -جل وعلا-: لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] فعلى المؤمن أن يتقي الله في جميع ما يأتي ويذر حسب شرع الله، وعليه أن يحذر الظلم والعدوان في أولاده أو في غيرهم، بل عليه أن يتحرى الحق أو العدل في كل شيء، وفق الله الجميع، نعم. المقدم: اللهم آمين، أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13061/توجيه-للاباء-الذين-لا-يعدلون-بين-اولادهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_556/55602.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية","فتاوى متنوعة"]},{"id":14590,"question":"إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (س. ح. أ) بعثت برسالة تقول فيها: هذه أول رسالة أكتبها إليكم، بعد أن وجدت أن هذا البرنامج هو خير الدروب التي تضيء للمسلم، ونحن معشر المسلمين دائمًا ما نحتاج لمثل هذه الأشياء تنير لنا طريق الدين، وسنة الرسول ﷺ، وأنا من المداومين على الاستماع لهذا البرنامج، وعليه وبعد أن وجدت طريقًا يمكن للإنسان أن يسأل فلدي سؤال عسى أن أجد الرد عليه وهو:أنا متزوجة ولدي طفل، وكنت حاملًا وزوجي يعمل بالسعودية، وعندما حضر إلينا بالسودان، قد نزل بمنزل شقيقه لضيق منزلنا، وقد أحضر إلي أشياء خاصة، وعندما أراد أن يسلمني هذه الأشياء قام بقسمتها بيني وبين زوجة شقيقه بالنصف، لدي سؤال:هل يجوز شرعًا هذه القسمة؟ وأنا كزوجة في الشرع، أريد ردًا واضحًا بما أني قد تضررت من هذه القسمة، وأرى كأنها ضرتي، وفي الختام أرجو أن أجد الرد.والسلام عليكم ورحمة الله.","title":"حكم إعطاء الرجل زوجة أخيه عطية مثل زوجته","answer":"الجواب: لا حرج في هذه القسمة، الزوج له الحرية في أن يعطيك، ويعطي زوجة أخيه، وزوجة عمه وزوجة أبيه، وله أن يعطي أيضًا من يرى من قريباته، لا حرج عليه في ذلك، ولا يجوز لك أن تكرهي ذلك، أو تضرري من ذلك، أو يكون عليك مشقة من ذلك إذا أحسن إليك، وأعطاك ما يجب لك من الكسوة والنفقة، فلا حرج عليه، إذا وسع الله عليه، وأحسن إلى زوجة أخيه من باب الصلة، ومن باب البر بأخيه، والمجاملة لأخيه، كونه سكن عندهم أيضًا، هذا من مكارم الأخلاق، ومحاسن الأعمال أن يكرم زوجة أخيه وزوجة عمه وزوجة أبيه.  وكذلك من مكارم الأخلاق أن يحسن إلى جيرانه وأقاربه جميعًا من ذكور وإناث. فينبغي أن تعينيه على هذا الخير، وأن تكوني زوجة صالحة تعين على الخير، وتساعد على بر الوالدين، وعلى صلة الرحم، وعلى إكرام الجيران، إذا أعطاك حقك، فإذا أعطاك ما يجب من الكسوة اللائقة، والحاجات اللائقة، ثم وسع الله عليه، وأعطى زوجات إخوته، أو أعطى أخواته أو عماته أو خالاته، أو نساء جيرانه على وجه ليس فيه ريبة ولا فتنة، فلا بأس بذلك، والحمد لله، هذا كله عمل طيب مشكور، ينبغي لمثلك أن يساعده على هذا، ويشكره على هذا؛ لأنه من مكارم الأخلاق، ومحاسن الأعمال إذا أدى حقك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13087/حكم-اعطاء-الرجل-زوجة-اخيه-عطية-مثل-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_635/nour_63510.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":14600,"question":"المستمع (ر. م. ش) من مصر، بعث برسالة طويلة يقول فيها: طلق والدي والدتي، وأنا جنين في بطنها، ثم كبرت وتزوجت، وأصبح عندي أولاد، وأنا أعيش مع والدتي، ولا أعرف والدي إلا بالاسم، لم يقم بالصرف علي أو تعليمي أو الاهتمام بي، وتزوج والدي من امرأة أخرى وأنجب منها أولادًا أصبحوا هم الذين يدبرون أعماله، ويتحكمون في مسئولياته، ولكنه في الآونة الأخيرة.الشيخ: أعد أعد.المقدم: يقول المستمع (ر.م.ش) من مصر، بعث برسالة يقول فيها: طلق والدي والدتي، وأنا في بطنها، ثم كبرت، وتزوجت وأصبح عندي أولاد، وأنا أعيش مع والدتي، ولا أعرف والدي إلا بالاسم، لم يقم بالصرف علي أو تعليمي، أو الاهتمام بي، وتزوج والدي من امرأة أخرى وأنجب منها أولادًا أصبحوا هم الذين يديرون أعماله، ويتحكمون في مسئولياته، ولكن في الآونة الأخيرة أصبح والدي يشتكيني لكل شخص في المدينة بأنني عاق، وبأنني أعمل في الخارج، ولا أبعث له نقودًا مع أنه غني.وسؤالي يا سماحة الشيخ: هل له الحق في أن أرسل له أي مبلغ من المال، والأمر بالصورة التي ذكرتها، ثم يستطرد في رسالته ويقول: والدتي غنية جدًا، حيث أنها تتاجر في الكثير من السلع، وليس لديها أولاد غيري، وتطلب مني أن أرسل لها نقودًا، مع أن حالتي المالية لا تسمح بذلك، حيث أن راتبي متواضع ومسئوليات الزوجة والأولاد كثيرة، هل يجب علي مع هذا أن أرسل لها نقودًا أم لا؟وإذا رفضت هل يدخل هذا في باب العقوق؟جزاكم الله خيرًا.","title":"حكم الإنفاق على الوالدين مع عدم الاستطاعة","answer":"الجواب: الواجب عليك -يا أخي- الحرص على بر والدك ووالدتك، ولو كان أبوك قصر في حقك، فالواجب عليك أن تحرص على بره، والإحسان إليه بالمكاتبة والكلام الطيب والزيارة إذا تيسرت، والأخذ بخاطره حتى لا يقع بينكما عقوق.  أما هو فالواجب عليه أن يعدل بينك وبين أولاده الآخرين؛ لأن الرسول  قال: اتقوا الله، واعدلوا بين أولادكم فإذا أعطاهم أعطاك، وساوى بينك وبينهم غير النفقة التي ينفقها عليهم النفقة العادية، إذا أعطاهم أشياء من أراضٍ أو سيارات أو غير ذلك، عليه أن يعدل بينكم، وأنت عليك أن تراعي خاطره بالكلام الطيب، والأسلوب الحسن والزيارة إذا أمكن؛ حتى لا يقع بينكما العقوق. أما أن تعطيهم من المال أو تعطي والدك من المال وأنت راتبك قليل ولا يكفي، وحده أن يكفيك وأسرتك وهما بخير، الوالد بخير، والوالدة بخير فلا يلزمك، لا يلزمك أن ترسل إليهما مالًا، ولكن تعتذر إليهما بالكلام الطيب، والأسلوب الحسن، وتقول: يا أبي، إن راتبي قليل، وأن مسئولياتي كثيرة، وأنه ما يحصل عندي فضل حتى أرسل إليك، وأنت -بحمد الله- في خير، وهكذا تقول للوالدة: أنت بحمد الله في خير، وأنا راتبي كذا وكذا، وأرجو مسامحتي، فتأخذ خاطرهما بالكلام الطيب، ولا يلزمك أن ترسل لهما مالًا، وهما غنيان، وأنت بحاجة إلى المال، لا يلزمك، لكن عالج الموضوع بالأسلوب الحسن، والكلام الطيب، والمكاتبة الحسنة حتى تكسب رضاهما، وفقك الله، ويسر أمرك. المقدم: آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13104/حكم-الانفاق-على-الوالدين-مع-عدم-الاستطاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_636/nour_63603.mp3","categories":["النفقات","الهبة والعطية"]},{"id":15141,"question":"هذا السائل يقول -يا سماحة الشيخ- من السودان: هل يجوز لي أن أمنع الهبة كالنخيل التي وهبها جدي تقربًا للسيد أو الولي؟","title":"حكم منع الولد ما أوقفه والده للأضرحة","answer":"الجواب: إذا كان جدك أو أبوك وقف نخلات، أو بيت على ضريح فلان، يبنى منه عليه، أو ينفق منه على تطييب المحل، أو البناء عليه، أو تجصيصه، أو ما أشبه ذلك، فالوقف باطل، هذا الوقف باطل، وهو يكون للورثة، يكون وقفًا باطلًا، ويكون للورثة، ولا يعتمد؛ لقوله ﷺ: من عمل عملًا ليس عليه أمرنا فهو رد ويقول ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد فلا بد أن تكون الأوقاف على الوجه الشرعي، فالوقف الذي لا يوافق الشرع يكون باطلًا. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13637/حكم-منع-الولد-ما-اوقفه-والده-للاضرحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56410.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":15263,"question":"سماحة الشيخ، تساهل الكثير من الناس في الانصراف عن أطفالهم، يبلغون الحادية عشرة، والثانية عشرة وهم مهملون لهم، هل من توجيه للآباء والأمهات؟","title":"توجيه لمن يهملون أولادهم ولا يحثونهم على الصلاة","answer":"الجواب: نعم، لا يجوز هذا، الواجب على الآباء والأمهات توجيه الأولاد ونصيحتهم، إذا بلغ سبعًا أن يؤمر بالصلاة، والمرأة والبنت تؤمر بالصلاة وتعلم، والولد كذلك يؤمر ويعلم، ويخرج به أبوه أو أخوه إلى المسجد، وإذا بلغ عشرًا يضرب؛ لقوله ﷺ: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر، وفرقوا بينهم في المضاجع هذا هو الواجب، متى بلغ عشرًا فأكثر يؤمر بالصلاة مع الناس، ويضرب إذا تخلف، يضربه أبوه أو أخوه الكبير أو عمه، أما إذا بلغ الحلم، فإنها تجب عليه تكون فريضة، إذا تركها كفر، نسأل الله العافية.  أما ابن سبع وابن ثمان وابن تسع هذا يؤمر ولا يضرب، نعم، الله المستعان. المقدم: الله المستعان، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13756/توجيه-لمن-يهملون-اولادهم-ولا-يحثونهم-على-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_565/56511.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية","فتاوى متنوعة"]},{"id":15286,"question":"سؤالها الآخر تقول: والدي من ذوي الأموال والعقارات، وله أولاد ذكور ومن الإناث، أنا وأختي، ولكنه لا يعدل بيننا في الهبات؛ فهو يعطي الأولاد أموالًا نقدًا وعقارات بدون مقابل، ولكي يتخلص من مطالبتنا يسجل عقود بيع بينهم صورية، وإذا طالبنا يهددنا بإعطائهم ما تبقى وحرماننا من كل شيء. علمًا أنه يصلي ويصوم ويقرأ القرآن، وإذا قلنا له: هذا حرام عليك يستهزئ بنا ويسخر منا، وحتى أختي الثانية تسبب في طلاقها من زوجها منذ ثلاثين سنة، ورفض تزويجها مرة أخرى حتى بلغ عمرها الآن خمسين سنة، ومع ذلك لا ينفق عليها، بل إخوتي مرة يعطفون عليها ويعطونها، ومرة أخرى يطردونها بسبب تأثير والدي عليهم، فقد زرع الكراهية في نفوسهم نحونا، إضافة إلى ما جرت عليه العادة عندنا من عدم تزويج الفتاة إلا من ابن عمها مهما كان، فما رأيكم في هذا؟ وبماذا تنصحون والدنا هذا؟","title":"حكم من لا يعدل بين أولاده في العطايا ويعضل بناته","answer":"الجواب: أولاً: الواجب على الرجل أن يتقي الله في أولاده، وأن يعدل بينهم في العطية، وليس له الجور والحيف، بل يجب أن يعدل بينهم في العطية، فيعطي الرجل ضعف المرأة كالميراث، هذا هو الصواب؛ لقول النبي ﷺ: اتقوا الله واعدلوا بين أولادكم ولما جاءه بشير بن سعد الأنصاري  وقد أعطى ابنه النعمان غلامًا قال له النبي -عليه الصلاة والسلام-: أكل ولدك أعطيته مثل هذا؟ قال: لا، قال: اتقوا الله واعدلوا بين أولادكم وقال لما أشهده: إني لا أشهد على جور فهذا يدل على أن التفضيل بين الأولاد، أو إعطاء بعضهم، وترك البعض جور وظلم، وهذا هو الصواب من أقوال أهل العلم كما دل عليه الحديث الشريف. فالواجب على أبيك تقوى الله، وأن يعدل في أولاده، وإذا لم يعدل وجب على الحاكم الشرعي أن يلزمه بالعدل، وأن ينقض العطايا التي فيها الحيف والجور، وإذا كانت بصور بيع لا حقيقة له يبطل هذه البيوع الباطلة إذا ثبت لدى الحاكم أنها حيلة، فالبيع الذي يكون بالحيلة باطل وجور وظلم، والله سبحانه أوجب على الآباء والأمهات العدل في أولادهم وألا يجوروا، وأن يحرصوا على أن يكونوا في البر لهم سواء. وكذلك ليس للوالد أن يمنع بناته الزواج، بل عليه أن يساعد في الزواج، ولا يجوز له أن يجبرها على ابن عمها، بل إذا جاء الكفء من بني عمها أو غيرهم وجب على الولي التزويج، سواء كان الولي أبًا أو غير أب، هذا هو الواجب، وقد جاء في الحديث: إذا خطب إليكم من ترضون دينه وأمانته فزوجوه، إلا تفعلوه تكن فتنة في الأرض، وفساد كبير والله -جل وعلا- قال: فََلا تَعْضُلُوهُنَّ[البقرة:232] نهى الأولياء عن العضل، فإذا عضل الوالد زالت ولايته، وساغ للقاضي أن يولي غيره من بقية العصبة الأقرب فالأقرب. فالمقصود: أن والدك إذا كان عمله ما ذكرت فقد أساء وعصى ربه، فعليه التوبة إلى الله، وعليه أن يعدل بين أولاده، وعليه أن يرد العقود الباطلة التي تحيل بها وسماها بيعًا، وليست ببيع، وإنما هي عطايا، وعلى الحاكم الشرعي إذا علم هذا بالبينة أن يبطل العقود، وأن يرد العطايا الجائرة، وأن يلزمه بالتسوية بين أولاده. كما أن على القاضي أن يلزمه بتزويج البنت التي يخطبها الكفء، يلزم القاضي أن يلزمه بالزواج، أو يعزله عن هذا الأمر، ويحكم عليه بالعضل، ويسمح للأقرب من العصبة بعد الوالد بالتزويج، هذا هو الواجب على الأولياء وعلى حكام الشرع في علاج، هذه المسائل، نسأل الله للجميع الهداية، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13785/حكم-من-لا-يعدل-بين-اولاده-في-العطايا-ويعضل-بناته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_681/nour_68103.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":15317,"question":"هذه رسالة من المستمع (ع. ع. س. الغامدي) يقول: كان والدي -رحمه الله- قد أوقف أرضًا زراعية بجانبها بئر، على أن يصرف ريع هذه الأرض في استمرار دلو على البئر بمعنى لغرض سقاية المارة الذين كانوا في السابق يمرون بهذه الأرض مشيًا على أقدامهم، أو ركوبًا على دوابهم من الحيوانات، فأوقف الأرض لهذا الغرض، والآن لم يعد هناك من يمر بهذه الأرض من المشاة، حتى يستفيدوا من السقي من هذه البئر بواسطة الدلو الموقوفة الأرض لأجل استمرار بقائه، وأيضًا الأرض تركت من الزراعة؛ لذا فليس لها ريع الآن.فأرشدونا إلى العمل الأفضل لنا فعله تجاه هذا الوقف.","title":"كيفية التصرف في الوقف الذي لم يعد يستفاد منه","answer":"الجواب: ينبغي في مثل هذا التشاور مع قاضي البلد في بيع الوقف هذا، وصرف ثمنه في وقف أنفع للمسلمين في بلد تنتفع بهذا الوقف في البركة ماء ينتفع بها الناس، أو في إيجاد حوض، بركة من الماء لسقي مواشيهم، أو ما أشبه ذلك مما يحل محل الدلو الأولى.  يتشاور صاحب الوقف هذا مع فضيلة القاضي فيما تنقل إليه هذه الأرض، تباع ويصرف ثمنها فيما يناسب ويجانس ما أراده الواقف السابق، فإن لم يتيسر شيء من ذلك صرف ثمنها فيما ينفع المسلمين من تعمير المساجد التي هي في حاجة إلى التعمير، أو ما أشبه ذلك مما يراه القاضي نافعًا للمسلمين، ومن جملة المصالح العامة، نعم.\nالمقدم: يعني: لو أنفق نقدًا مثلًا سلم إلى أحد من المحتاجين أو وزع؟\nالشيخ: لا، إذا ينصرف في مثله يكون أحسن، إذا تيسر صرفه في بركة تنفع المسلمين في بعض القرى، أو صرفه في إيجاد بئر تسقي بعض المارة، أو تسقي بعض الفقراء في بعض القرى المحتاجة، أو بعض البادية إذا وجد شيء من هذا، فهو أفضل، حتى يجانس ما أراده الواقف، فإن ما تيسر صرف فيما هو أنفع وأبقى مثل المساجد وأشباهه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13819/كيفية-التصرف-في-الوقف-الذي-لم-يعد-يستفاد-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_676/nour_67606.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":15482,"question":"السائلة في آخر أسئلتها تقول: سماحة الشيخ، جزاكم الله عنا وعن جميع المسلمين خير الجزاء، هل تعتبر الهدية رشوة في هذه الحالة، حيث بأنها قامت بعمل خير، وهو تدريس بنت الجيران، وقالت: إذا نجحت فلك هدية، وقلت لها: لا أريد هدية؛ لأنني أعمل هذا لله، ولكنها أصرت عليها، فما حكم أخذ هذه الهدية سماحة الشيخ؟","title":"ما حكم قبول الهدية على عمل الخير؟","answer":"الجواب: ما دمت قصدت وجه الله في عدم أخذ الهدية فالأحوط لك أن لا تأخذي شيئًا، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14008/ما-حكم-قبول-الهدية-على-عمل-الخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56903.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":15510,"question":"هذه رسالة من السائل أبو إهاب مصري، يعمل بالكويت، بعث بعدة أسئلة في سؤاله الأول يقول: أنجب والدي ستة أولاد وبنتًا واحدة، ولقد جاهد -رحمه الله- حتى أتم تعليمنا إلا واحدًا من إخوتي شاء الله أن لا ينال حظه من التعليم مثلنا، وذلك لرغبة من الوالدة في أن يظل مع والده يعمل معه في فلاحة الأرض، حيث أننا من أبناء الريف، وقبل وفاة الوالد طلبت أنا من والدي أن يخص أخي المذكور بقدر معين من الأرض التي يملكها عوضًا له عن جهده طوال سنوات عدة، ولكونه لم ينل حظه من التعليم مثلنا، والحقيقة أنه -رحمه الله- رفض ذلك مرارًا، ولكنه أمام إلحاحي وإلحاح الوالدة وبعض الإخوة وافق على أن يحرر لأخي عقد بيع وشراء صوري لقطعة محددة من الأرض، ولكن دون أن يقبض منه أي ثمن، بل أخذ عليه صكًا بمبلغ سبعمائة جنيه، فما مدى صحة هذا العقد الذي تم بين الوالد وبين أخي؟علمًا بأن العقد موجود عندي بصفة أمانة لحين إتمام الإجراءات، وهل الصك الذي أخذه والدي على أخي يدخل ضمن تركته ويطالب به أخي أم لا؟","title":"حكم الأرض التي باعها الأب لأحد أبنائه قبل موته","answer":"الجواب: إذا كان الواقع ما ذكره السائل فالصك المذكور لا عبرة به؛ لأنه كذب وحيلة؛ فلا وجه له، لكن إذا سمح إخوته الورثة جميعًا بهذه القطعة لهذا الأخ للسببين المذكورين؛ لكونه ساعد أباه، ولكونه لم يتعلم، فلا بأس إذا سمحوا له بهذه القطعة، أو سمح بعضهم، فمن سمح منهم سقط حقه من هذه القطعة، ومن لم يسمح فهو على حقه، أما هذا العقد المزور فلا قيمة له، ولا يلتفت إليه، نعم.\nالمقدم: إنما تعتبر كهبة يعني من الورثة.\nالشيخ: إذا سمحوا بها.\nالمقدم: إذا سمحوا بها صحيحة. الشيخ: ومن لم يسمح فهو على حق.","link":"https://binbaz.org.sa/fatwas/14067/حكم-الارض-التي-باعها-الاب-لاحد-ابناىه-قبل-موته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_703/nour_70303.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":15628,"question":"يقول السائل: في هذه الأيام يفضل التمييز بين الأبناء، يقول: وهذا يخلق عداوة بين الإخوان فيما بينهم أفيدونا بتوجيه الآباء ونصيحتكم. جزاكم الله خيرًا.","title":"ما النصيحة للآباء في المفاضلة بين الأبناء؟","answer":"الجواب: لا يجوز للآباء تفضيل بعض الأولاد على بعض، لا يجوز لهم ذلك، بل هذا منكر؛ النبي ﷺ لما سأله بشير بن سعد أن يعطي النعمان ولده غلامًا قال: أعطيت ولدك كلهم؟ قال: لا، قال: اتقوا الله واعدلوا بين أولادكم وأراد أن النبي ﷺ يشهد فقال: إني لا أشهد على جور سماه النبي ﷺ جورًا. فالمقصود: أنه لا يجوز للأم ولا للأب التفضيل بين الأولاد، بل يجب التسوية بينهم للذكر مثل حظ الأنثيين، فلا يجوز أن يعطى زيد كذا، ويترك الآخر، لا، بل يجب التعديل بين الأولاد ذكورهم وإناثهم؛ ولهذا في الحديث الآخر: أيسرك أن يكونوا لك في البر سواء؟ قال: نعم، قال: فهكذا؛ لأنه إذا فرق بينهم ساءت أحوالهم، وربما قطعوه أيضًا. فالواجب على الأب والأم والجد والجدة عدم التفضيل، بل يجب العدل للذكر مثل حظ الأنثيين، إذا أعطى الذكر مائة يعطي الأنثى خمسين، وإذا أعطى الرجل ألفًا يعطي الأنثى خمسمائة وهكذا، يجب التعديل؛ لقوله ﷺ: اتقوا الله واعدلوا بين أولادكم ولقوله لـبشير بن سعد الأنصاري لما أراد أن يشهده على عطيته للنعمان وحده قال: إني لا أشهد على جور وقال لـبشير: أيسرك أن يكونوا لك في البر سواء؟ قال: نعم، قال: فلا إذًا يعني: فلا تخص بعضهم، سوِّ بينهم حتى يكونوا كلهم في البر لك سواء، نعم. المقدم: أحسن الله إليكم وبارك فيكم..","link":"https://binbaz.org.sa/fatwas/14169/ما-النصيحة-للاباء-في-المفاضلة-بين-الابناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_571/57111.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية","فتاوى متنوعة"]},{"id":15696,"question":"من أسئلة السائل إبراهيم من الرياض، يقول: ما هي حقوق الأبناء على الآباء؟جزاكم الله خيرًا.","title":"حقوق الأبناء على آبائهم","answer":"الجواب: حق الولد على أبيه أن ينفق عليه، مادام صغيرًا، ومادام عاجزًا عن النفقة، ينفق عليه أبوه إذا استطاع، ويؤدبه، ويعلمه ما أوجب الله عليه، وينهاه عما حرم الله عليه، ويكون قدوةً له في الخير، بفعله وقوله.  هكذا يجب على الآباء أن يتقوا الله، وأن يكونوا قدوةً صالحة لأولادهم، وأن يعلموهم، ويوجهوهم إلى الخير، ويؤدبوهم إذا خالفوا الشرع، كما قال النبي ﷺ: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر، وفرقوا بينهم في المضاجع. وإذا كان الولد فقيرًا -والأب غنيًا- وجب عليه أن ينفق عليه، وإن كان كبيرًا، ينفق عليه حتى يوسع الله عليه، ويجد عملًا يستطيع النفقة منه، وأهم شيء العناية بدينه، كونه يعتني بدينه، يوجهه إلى الخير، يأمره بطاعة الله، ينهاه عن محارم الله، يأمره بالصلاة، يأمره بكل ما أمر الله به ورسوله، وينهاه عن كل ما نهى الله عنه ورسوله، ويكون قدوةً أيضًا في أفعاله، يكون الأب قدوة، والأم تكون قدوة في أفعالهما وأقوالهما الطيبة، قدوةً لأولادهما. المقدم: أحسن الله إليكم يا شيخ.","link":"https://binbaz.org.sa/fatwas/14253/حقوق-الابناء-على-اباىهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_573/57305.mp3","categories":["تربية الأولاد","النفقات","الهبة والعطية"]},{"id":15759,"question":"رسالة وصلت إلى البرنامج من جمهورية مصر العربية محافظة المنيا، وباعث الرسالة المستمع خالد طلعت عبدالله علي، الأخ خالد يقول في رسالته: لرجل ابنان متزوجان، وكلاهما يعول أسرة، أحد هذين الابنين حالته ميسرة، والآخر نفقاته كثيرة، ويحتاج إلى بعض العون، فقام الأب بتخصيص دخل ثابت لابنه المحتاج هذا برغبة الوالد، ودون طلب من ابنه هذا، إلا أن الابن الآخر ثار على والده وأخيه، واعتبر أن أباه يفضل أخاه عليه. و هل هذا جائز شرعًا؟ علمًا بأن الابن ينتفع بهبة والده له في حياته فقط.جزاكم الله خيرًا.","title":"حكم إنفاق الأب على الابن الفقير دون الغني","answer":"الجواب: إذا كان أحد الابنين فقيرًا، وليس عنده أسباب تقوم بحاله، فعلى الوالد أن ينفق عليه إذا كان قادرًا، والابن الغني لا حق له في ذلك، فإذا كان عنده أولاد بعضهم فقراء، وبعضهم أغنياء، والوالد يقدر على النفقة، وجب عليه الإنفاق على الفقراء، وإن كانوا كبارًا، إذا لم يكن عندهم أسباب تغنيهم، ولا كسب يغنيهم؛ لأن النفقة أمر لازم على الوالد أن ينفق على ولده الفقير. أما إذا كانوا كلهم أغنياء، فليس له أن يخص أحدًا بالعطية؛ لقول النبي ﷺ: اتقوا الله، واعدلوا بين أولادكم فالواجب أن يعدل إن كانوا فقراء، أنفق عليهم، وأعدل فيهم، وإن كانوا أغنياء أعدل فيهم أيضًا، أعطاهم جميعًا، أو تركهم جميعًا، أما إذا كان أحدهم فقيرًا، والبقية أغنياء، أو أكثرهم فقراء، وبعضهم أغنياء، فإنه ينفق على الفقير، وليس هذا بظلم، بل واجب عليه أن ينفق إذا كان الفقير ما عنده أسباب، ما عنده كسب، لا يستطيع الكسب، فإن الوالد إذا كان قادرًا عليه ينفق عليه ويواسيه بنفقة أمثاله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14346/حكم-انفاق-الاب-على-الابن-الفقير-دون-الغني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_741/nour_74106.mp3","categories":["الهبة والعطية","النفقات","بر الوالدين"]},{"id":16231,"question":"آخر سؤال لها تقول فيه: والدي للأسف الشديد لا يصلي، ويقوم أحيانًا بإعطائي بعض النقود في المناسبات، كالأعياد مثلًا، فهل يجوز لي أخذها؟ وإذا أخذتها، وتصدقت بها؛ فهل تصح الصدقة، أم لا؟ جزاكم الله خيرًا.","title":"حكم قبول العطية من أب لا يصلي","answer":"الجواب: لا بأس بأخذ الدراهم من والدك، ولا بأس بالصدقة بها، أو الانتفاع بها، لا حرج في ذلك، مع النصيحة لوالدك بالكلام الطيب.. تخويفه من الله -جل وعلا- .. حثه على الصلاة.. كذلك تشجيع أعمامك -إن كان لك أعمام- أو إخوة كبار ينصحونه، أو جيران جيدين ينصحونه، لا تغفلي، ولا يغفل إخوانك، ولا أعمامك، عليكم أن تتقوا الله فيه، وأن تنصحوه، وأن تستمروا في ذلك، أما هديته فاقبلوها، لا حرج في ذلك. نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14911/حكم-قبول-العطية-من-اب-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_751/nour_75118.mp3","categories":["الهبة والعطية","الدعوة والدعاة"]},{"id":16254,"question":"تقول السائلة: رجل عنده أولاد وبنات، فقام بإعطاء الأولاد مبالغ، وقطع أراضي وهبات، دون أن يعطي البنات، هل يجوز له ذلك؟","title":"وجوب العدل بين الأولاد في العطية","answer":"الجواب: الواجب على الوالد أن يعدل بين أولاده؛ الذكور والإناث، وهكذا الوالدة الأم يجب أن تعدل؛ لأن الرسول ﷺ قال: اتقوا الله، واعدلوا بين أولادكم هكذا قال -عليه الصلاة والسلام-: اتقوا الله، واعدلوا بين أولادكم. فالواجب على الأب إذا أعطاهم أراضي، أو نقودًا، أو إبلًا، أو غنمًا، أو غير ذلك أن يعدل بين الذكور والإناث للِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ [النساء: 11] كالإرث، فإذا أعطى الرجل مائة ريال، يعطي البنت خمسين ريالًا، وإذا أعطى الولد عشرة آلاف، يعطي البنت خمسة آلاف.. وهكذا، وإذا أعطى الولد غنمًا، أو إبلًا، أو بقرًا، يعطي البنت مثل ذلك، النصف، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14937/وجوب-العدل-بين-الاولاد-في-العطية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58102.mp3","categories":["تربية الأولاد","الهبة والعطية"]},{"id":16271,"question":"لها سؤال قريب في معناه من الأول تقول: إذا أهدى لي شخص طعامًا، سواءً كان ذلك الشخص جارًا، أو قريبًا، أو صديقًا، وهو لا يصلي، ولا يصوم، ويشرب الخمر، هل يجوز قبول هديته؟","title":"حكم قبول هدية من لا يصلي ويجاهر بالمعاصي","answer":"الجواب: هذا فيه تفصيل: إن كان قبولها يرجى فيه خير، وأن الله يهديه، ويقبل من المهدى إليه النصيحة، ويتأثر؛ فلا مانع من قبولها، لكن إذا كان فيها لحم لا، لا تأكل اللحم إذا كان لا يصلي، إلا إذا كانت فاكهة شيء ما يحتاج ذبحًا، فاكهة، أو شبه فاكهة، لا بأس.  أما إذا كان لا، معاند، ولا يرجى فيه خير، لا تقبل هديته، اهجره، ولا تقبل هديته، لعل الله يهديه، لا تقبل هديته، ولا تقبل دعوته، ولا تزوره، بل يستحق الهجر؛ لتركه الصلاة، وإعلانه الخمر، والمعاصي الظاهرة، فهذا يستحق الهجر؛ لعله يتوب، فيتوب الله عليه. أما إذا كان في قبول هديته مصلحة شرعية، أو في زيارته مصلحة شرعية للدعوة إلى الله، وتوجيهه إلى الخير، وإنكار المنكر عليه؛ لعل الله يهديه بأسبابك، فهذا لا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14978/حكم-قبول-هدية-من-لا-يصلي-ويجاهر-بالمعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_809/nour_80907.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":16285,"question":"لها سؤال قريب في معناه من الأول تقول: إذا أهدى لي شخص طعامًا، سواءً كان ذلك الشخص جارًا، أو قريبًا، أو صديقًا، وهو لا يصلي، ولا يصوم، ويشرب الخمر، هل يجوز قبول هديته؟","title":"حكم قبول هدية من لا يصلي ويجاهر بالمعاصي","answer":"الجواب: هذا فيه تفصيل: إن كان قبولها يرجى فيه خير، وأن الله يهديه، ويقبل من المهدى إليه النصيحة، ويتأثر؛ فلا مانع من قبولها، لكن إذا كان فيها لحم لا، لا تأكل اللحم إذا كان لا يصلي، إلا إذا كانت فاكهة شيء ما يحتاج ذبحًا، فاكهة، أو شبه فاكهة، لا بأس.  أما إذا كان لا، معاند، ولا يرجى فيه خير، لا تقبل هديته، اهجره، ولا تقبل هديته، لعل الله يهديه، لا تقبل هديته، ولا تقبل دعوته، ولا تزوره، بل يستحق الهجر؛ لتركه الصلاة، وإعلانه الخمر، والمعاصي الظاهرة، فهذا يستحق الهجر؛ لعله يتوب، فيتوب الله عليه. أما إذا كان في قبول هديته مصلحة شرعية، أو في زيارته مصلحة شرعية للدعوة إلى الله، وتوجيهه إلى الخير، وإنكار المنكر عليه؛ لعل الله يهديه بأسبابك، فهذا لا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14978/حكم-قبول-هدية-من-لا-يصلي-ويجاهر-بالمعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_809/nour_80907.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":16340,"question":"عندنا وعند سنة الوليمة في الزواج يكون هناك دفتر يسجل عليه أسماء الذين يدفعون نقودًا للعريس، وعندما تكون هناك وليمة عند أحد الذين دفعوا للعريس، يخرج العريس الأول الدفتر ليرى كم دفع له من قبل هذا العريس الثاني، ثم يدفع هو زيادة على ما دفعه له الأول، فهل هذا شيء مباح؟الشيخ: أعد.المقدم: يقول: عندنا وفي بلدنا -ويسمي بلده سماحة الشيخ- وعند سنة الوليمة في الزواج يكون هناك دفتر يسجل عليه أسماء الذين يدفعون نقودًا للعريس، وعندما تكون هناك وليمة عند أحد الذين دفعوا للعريس يخرج العريس الأول الدفتر ليرى كم دفع له هذا العريس، ثم يدفع هو زيادة على ما دفعه له الأول، فهل في هذا شيء من الحرمة، وهل هو نوع من الربا؟ جزاكم الله خيرًا.","title":"ما حكم دفع مبالغ للعريس كمساعدة؟","answer":"الجواب: لا حرج في ذلك إذا كانت عادة عندكم لا حرج، الحمد لله؛ لأنه من باب المساعدة، والتعاون على الخير، وهذه عادة بين الناس مواساة للعريس بالمال، وبغير المال من الأشياء الأخرى، كل هذا تختلف فيه عادات الناس، هذا يدفع دراهم، وهذا يدفع أشياء أخرى. فالمقصود: أن هذه العادات لا حرج فيها في التعاون على الخير على البر والتقوى، ولا بأس إن شاء الله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15034/ما-حكم-دفع-مبالغ-للعريس-كمساعدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_714/nour_71403.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":16820,"question":"تقول: المشكلة الثانية في رسالتي يا سماحة الشيخ: هو التفرقة بين أولادي، هذا الزوج متزوج من امرأة ثانية، ويفضل أولاده من الأم الثانية -من الزوجة الثانية- ويحبهم كثيرًا، ويعطف عليهم، أما أنا فلي الإهمال، ولأولادي إهمال كثير، تقول: ما توجيه سماحتكم؟","title":"توجيه لمن يفضل أولاده من الزوجة الثانية على الأولى","answer":"الجواب: الواجب على الزوج أن يعدل بين الزوجتين، أو الثلاث، أو الأربع، عليه العدل، وعليه العدل في أولاده أيضًا، هذا هو الواجب على الزوج، وأن يتقي الله في ذلك، والله يقول: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] ويقول سبحانه: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ البقرة:228] فالواجب عليه العدل، وتحري العدل، وهكذا في أولاده، يقول النبي ﷺ: اتقوا الله، واعدلوا بين أولادكم.  فليس له أن يحيف كأن يعطي أولاد إحدى الزوجتين ما لا يعطيه أولاد الأخرى، أو يخاطبهم، ويلين معهم بالكلام الطيب، والآخرون بخلاف ذلك، لا يجوز هذا، بل يجب عليه العدل في قوله، وفي أعماله، وفي ماله. وهكذا مع الزوجتين، يعدل في الزوجتين في قسمه بينهما، وفي خطابه لهما، وعدم الظلم لإحداهما، أو لإحداهن إن كن ثلاثًا فأكثر، يجب عليه العدل في كلامه، وسيرته، ومعاشرته، ونفقته إذا كن سواء، والأولاد كذلك يجب أن يعدل بينهم، وليس له أن يخص بعضهم بشيء، يقول ﷺ: اتقوا الله، واعدلوا بين أولادكم.  فإذا أعطى ولد فلانة؛ يعطي لولد الأخرى مثله، إلا إذا كانوا مرشدين، وتسامحوا؛ فلا بأس، إذا كانوا مرشدين، وسامحوه قالوا: نسامحك يا والد، وسامحوه، وهم مرشدون؛ لا بأس، وإلا فالواجب عليه العدل للذكر مثل حظ الأنثيين فإذا أعطى ولد فلانة مائة؛ يعطي الآخر مائة، إذا أعطاه ألفًا؛ يعطيه ألفًا، والأنثى نصف ذلك؛ إذا أعطى الرجل مائة يعطيها خمسينًا، وإذا أعطى الرجل ألفًا يعطيها خمسمائة، هذا الواجب، وإذا كانت الزوجتان متماثلتين في النفقة؛ أنفق عليهما سواء، فإذا كانت إحداهما عندها أولاد أكثر، كل واحدة ينفق عليها بقدر حاجتها.  المقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم، وفي علمكم ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/15569/توجيه-لمن-يفضل-اولاده-من-الزوجة-الثانية-على-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_585/58517.mp3","categories":["الهبة والعطية","تعدد الزوجات"]},{"id":17052,"question":"أحمد سالم له هذا السؤال، يقول: سماحة الشيخ! عندنا أراضي زراعية وقف لمسجد صغير وقديم، فهل يجوز لنا أن نبيع بعض هذه الأوقاف لمصلحة إنشاء مسجد كبير، ومتسع للقرية؟ علمًا بأن أصحاب الوقف أموات، وهذه المزارع الموقوفة لا يستفيد المسجد القديم من وقفها بشيء؛ لأنها بأيدي أشخاص لا يؤدون حقها.","title":"حكم بيع أراضي الوقف وبناء مسجد بثمنها","answer":"الجواب:  عليكم مراجعة المحكمة، هذه المسائل من خصائص المحاكم، فعليكم أن تراجعوا المحكمة في هذا الأمر العظيم، وفيما تراه المحكمة الكفاية، إن شاء الله. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15841/حكم-بيع-اراضي-الوقف-وبناء-مسجد-بثمنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58727.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":17114,"question":"أيهما أفضل: الإثابة على الهدية عندما تعطى لي، أم إنفاق المال على الوالدين والأقربين؟ علمًا بأنني لا أستطيع الجمع بينهما؟","title":"استحباب الإثابة على الهدية","answer":"الجواب: كان النبي ﷺ إذا أهدي إليه هدية يقبلها، ويثيب عليها من جاء له هدية، وصاحبها يمكن أن يقبل الثواب يثاب، يعني: يعطى مقابل. أما إذا كان لا، ما يريد الثواب فلا حرج، إذا كان إنما هي صدقة لأجل فقره، أعطاه إياه لأجل فقره، أو أعطاه إياه من الزكاة هذا ما يحتاج أن يثاب، أما الهدية العادية التي للتحبب فالأفضل أن يقابل، ويعطى مقابل هديته، كان الرسول ﷺ يقبل الهدية ويثيب عليها، اللهم صل عليه. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15921/استحباب-الاثابة-على-الهدية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58911.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":17262,"question":"السائل يقول في هذا  يا سماحة الشيخ، والدي كتب الميراث لنا نحن البنين دون البنات، وترك زوجته وأخواتي البنات؛ بحجة أن الميراث بسيط، وأن أخواتي البنات تعلمن، وعملن، وجهز لهن بيت الزوجية، وهذا يعادل ميراثهن، ما نصيحتكم للآباء حول هذا الموضوع يا سماحة الشيخ؟","title":"حكم تخصيص الأبناء بالميراث دون البنات","answer":"الجواب: لا يجوز للآباء أن يخصوا الأبناء بشيء، بل الواجب أن يدعوا التركة للجميع: لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11] أما ما أعطاهن وقت الزواج هذا شيء آخر ما له تعلق بالورث، أما الورث يجب أن يكون بين الجميع على قسمة الله، ولا يجوز للأب أن يخص الذكور بشيء، ولا أن يخص البنات بشيء، بل يتركهم على قسمة الله: يُوصِيكُمُ اللَّهُ فِي أَوْلادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11] ولا يجوز أن يخص أحدًا منهم بشيء، لا كبيرًا، ولا صغيرًا، ولا عالمًا ولا جاهلًا، ولا ذكرًا ولا أنثى، بل يجب أن يترك الأمر على قسمة الله بين الجميع. نعم. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16101/حكم-تخصيص-الابناء-بالميراث-دون-البنات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_592/59213.mp3","categories":["الفرائض","الهبة والعطية"]},{"id":17410,"question":"هذه مستمعة من الأردن كتبت -الحقيقة- سؤالًا طويلًا، ملخصه: سماحة الشيخ -وقد كتبت هذه الرسالة بأسلوبها الخاص- تقول: لقد جرت العادة في قريتنا بأن البنات لا يرثوا، وإنما يعطون من بعض المال مقابل أن تتنازل هذه البنات لإخوتها عن حصتها في الميراث، ويقولون: بأنه بيع وشراء، وأنا أحرص على إرضاء والدي، وقد عرض علينا والدي -نحن البنات- مبلغًا من المال مقابل التنازل لإخواني عن نصيبنا نحن البنات، تقول: علمًا بأن المال من والدي، وليس من إخوتي، وقد قلت لوالدي: بأن هذا لا يجوز، وبأن ذلك يعرضه للعذاب، ولكن إخوتي يقولون لأبي: بأنهم لن يعملوا بالأرض، ولا بالشجر إلا إذا سجل بأسمائهم، وأبي مصر على الموافقة، فنرجو من سماحة الشيخ الإجابة.","title":"حكم حرمان البنات من الإرث","answer":"الجواب: لا يجوز للأب أن يخص البنين بالورث، ولا أن يلزم البنات بأن يأخذن عوضًا، هذا منكر، هذا من عمل الجاهلية، ولا يجوز، بل يجب أن يساعد على الأمر الشرعي، وأن تكون التركة للجميع، للبنين والبنات للذكر مثل حظ الأنثيين كما قال الله سبحانه: يُوصِيكُمُ اللَّهُ فِي أَوْلادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:12]. وهكذا الإخوة الأشقاء، والإخوة لأب يرثون للذكر مثل حظ الأنثيين كما قال -جل وعلا-: وَإِنْ كَانُوا إِخْوَةً رِجَالًا وَنِسَاءً فَلِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:176] يعني: الإخوة الأشقاء، والإخوة لأب، هذا واجب، ولا يجوز للأب، ولا الأخ أن يحيد عن هذا الأمر، هذا حرام منكر، من سنة الجاهلية، كان أهل الجاهلية لا يورثون النساء، والصبيان، ويورثون الذكور الكبار، وهذا غلط كبير، لا .... للمسلم أن يتشبه بالكفار، بل التركة للصغار، والكبار، والذكور، والإناث على قسمة الله، وليس للأب أن يلزم البنات، أو يعطيهم شيئًا من غير رضاهم ليسمحوا، لا، بل يجب أن يمكنوا من إرثهم، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16275/حكم-حرمان-البنات-من-الارث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77111.mp3","categories":["الفرائض","الهبة والعطية","نصائح وتوجيهات"]},{"id":17558,"question":"هذا سائل من سوريا فهمت الحقيقة من رسالته الطويلة وأسلوبه بحكم الشرع في نظركم فضيلة الشيخ في الأب الذي يفرق بين أولاده في الأعطية؟","title":"الواجب العدل بين الأبناء في العطية","answer":"الجواب: لا يجوز، الواجب على الآباء العدل؛ لأنه ثبت عن النبي ﷺ أنه قال: اتقوا الله واعدلوا بين أولادكم، فلا يجوز للأب ولا للأم التفضيل بين الأولاد بل يجب التسوية للذكر مثل حظ الأنثيين، هذا هو الواجب على الرجل والمرأة في أولادهم، لكن لو كانوا مرشدين، وسمحوا أن يخص واحد منهم بشيء فلا بأس إذا كانوا مرشدين وسمحوا لأبيهم أو لأمهم أن تخص أحدًا منهم بشيء لأسباب اقتضت ذلك فلا بأس، أما أن يخص أحد دون أحد، أو يفضل أحد على أحد؛ فلا يجوز إلا بإذن المرشدين. نعم.\nالمقدم: شكر الله لكم يا سماحة الشيخ وبارك الله فيكم وفي علمكم ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/16487/الواجب-العدل-بين-الابناء-في-العطية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_775/nour_77523.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":17670,"question":"من أسئلة السائلة هيلة المرشد من القصيم تقول: يا سماحة الشيخ حفظكم الله، هل تكفر الذنوب بالهدايا والأعطيات للفقراء والمحتاجين وذوي القرابة والأصدقاء؟","title":"هل الهدايا والأعطيات تكفر الذنوب؟","answer":"الجواب: الصدقات تطفئ الخطيئـة كما قال ﷺ: الصدقة تطفئ الخطيئة كما يطفئ الماء النار الصدقات ثوابها عظيم وأجرها كبير، وهي من أسباب تكفير الخطايا وحط السيئات.\nأما الهدايا فيها تفصيل، الهدايا إذا أهداها لقريبه لصلة الرحم هذه من أسباب تكفير السيئات، صلة الرحم عمل صالح، أما إذا أهداها لشيء آخر؛ لمجاملة أو لطلب مكافأة، هذا لم يقصد بها عملًا صالح.\nأما إذا أهداها لقريبه أو لأرحامه أو لفقير تسمى صدقة، وللقريب تسمى صلة، صلة رحم يؤجر عليها. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16601/هل-الهدايا-والاعطيات-تكفر-الذنوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59434.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":18131,"question":"الحاج علي الريشي من ليبيا وأخونا فيصل بن عبد العزيز أحمد الهندي، يسألون سماحة الشيخ عن تفضيل بعض الأبناء عن بعض، لعل رسالة الأخ من ليبيا توضح بعض الشيء فيقول: أسأل عن قضية لي: وهي أن لي ثلاثة أبناء منهم اثنان لهما مسكنان، أما الثالث وهو الأصغر عنده قطعة أرض غير مبنية، فالأول قمت ببناء منزله على نفقتي؛ لأنه عاجز، وبه مرض الصرع عافاكم الله، ولا يستطيع عمله بنفسه، أما الأوسط فقد بنى منزله بقرض من أحد المصارف، وأما الأصغر فلم يتمكن من البناء في الوقت الحالي، ولي منزل باسمي كبير قررت أن أتنازل عنه لبناتي الأربعة ووالدتهن، علمًا بأنهن جميعًا متزوجات، ولكن قد يحتجن يومًا للمنزل، فهل يحق لابني الصغير نصيب في المنزل هذا، دلوني حتى ألاقي وجه ربي نظيفًا؟ جزاكم الله خيرًا.","title":"وجوب العدل بين الأولاد في العطية","answer":"الجواب: الواجب عليك أن تعدل بين أولادك ذكورهم وإناثهم، وليس لك أن تخص البنات بشيء سواء كن متزوجات أو غير متزوجات لا بالبيت ولا بغيره، لقول الرسول ﷺ: اتقوا لله واعدلوا بين أولادكم، فعليك أن تعدل بينهم ذكورهم وإناثهم إلا أن يسمح بعضهم فالذي يسمح يسقط حقه، إذا سمح بعضهم سقط حقه، وإذا سمح الأولاد الثلاثة بالبيت للبنات سقط حقهم والحمد لله. أما أن تخص أحدًا بشيء، فليس لك أن تخصه بشيء، لقوله عليه الصلاة والسلام: اتقوا الله واعدلوا بين أولادكم، فهم في الذمة، وهم في الحق سواء، فعليك أن تعدل بينهم أو تترك إعطاءهم، أما أن تعطي البنات وتدع الذكور أو تزيد هذا على هذا فليس لك ذلك، بل عليك أن تسوي بينهم كالميراث للذكر مثل حظ الأنثيين، هذا هو الواجب عليك، إلا إذا سمح المكلف منهم الرشيد سمح عن حقه، فلا بأس بذلك. نعم.","link":"https://binbaz.org.sa/fatwas/17176/وجوب-العدل-بين-الاولاد-في-العطية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_852/nour_85204.mp3","categories":["تربية الأولاد","الهبة والعطية"]},{"id":18144,"question":"يقول السائل من الكويت: هل يجوز وضع المصاحف في المساجد؟ وهل يكون لمن وضعها أجر على كل حرف يقرأ من هذا المصحف، ووضع هذا المصحف بنية أن يكون أجر القارئ للمتوفى فهل هذا مشروع؟","title":"ثواب من أوقف المصاحف في المسجد","answer":"الجواب: وضع المصاحف في المساجد مشروع؛ لأنه يعين من جاء للمسجد على القراءة، وصاحبه له أجر، يرجى له أجر كبير؛ لأنه ممن أعان على الخير، والرسول  يقول: والله في عون العبد ما كان العبد في عون أخيه، ويقول ﷺ: من كان في حاجة أخيه كان الله في حاجته. وإذا سبل المصاحف للأموات، أو كُتبَ علم؛ فلهم أجر في ذلك، إذا سبل مصحفًا، أو كتاب علم من كتب الحديث الشريف، أو من كتب التفسير، أو الفقه؛ فله أجر في ذلك، وإذا نوى هذا الوقف لأبيه أو أمه فله أجر في ذلك، وللموقوف له أجر في ذلك. المقدم: الحمد لله.","link":"https://binbaz.org.sa/fatwas/17194/ثواب-من-اوقف-المصاحف-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78117.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":18147,"question":"بالنسبة سماحة الشيخ حفظكم الله إلى إهداء المصحف حكمه يا شيخ؟الشيخ: ما معنى إهدائه؟المقدم: حكم إهداء المصحف، زميل لي أهديت له مصحفًا؟","title":"ما حكم إهداء المصحف؟","answer":"الجواب: هذا طيب، من باب الهبة، من باب التعاون على البر والتقوى، إذا أهديته إليه فأنت مشكور، لا بأس، طيب. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17195/ما-حكم-اهداء-المصحف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78118.mp3","categories":["الهبة والعطية"]},{"id":18148,"question":"سماحة الشيخ! تساهل كثير من الأسر في أبنائهم، وهم الحقيقة صغار، ثم يصعب عليهم في الكبر، هل من توجيه؟","title":"توجيه لمن يتساهل في تربية أبنائه","answer":"الجواب: هذا من المصائب العظيمة، التساهل من المصائب العظيمة، والواجب على الأب والأم والإخوة أن لا يتساهلوا في هذا، بل عليهم أن يجتهدوا في توجيه الأبناء والشباب إلى الصلاة، وإلى كل خير، وتحذيرهم مما حرم الله من السب والشتم والعقوق وغيرها من الفواحش والتدخين، وشرب المسكر وغير هذا من المنكرات. ومن أهم شيء بل أهم شيء بعد الشهادتين الصلاة، فعليهم أن يلزموا أولادهم بالصلاة، ويضربوا من تخلف عنها إذا كان بلغ عشرًا فأكثر، هذا هو الواجب على الآباء والأمهات، والإخوة الكبار مع الصغار، هذا من التعاون على البر والتقوى، وقد قال الله سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ[التوبة:71]، وقال النبي ﷺ: من رأى منكم منكرًا فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه، وذلك أضعف الإيمان. والوالد مأمور بأن يؤدب أولاده، بالضرب إذا بلغوا عشرًا فأكثر، حتى يستقيموا حتى يصلوا مع الناس.نعم. المقدم: أحسن الله إليكم سماحة الشيخ، وبارك فيكم على هذا التوجيه الطيب المبارك.","link":"https://binbaz.org.sa/fatwas/17188/توجيه-لمن-يتساهل-في-تربية-ابناىه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78116.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية","فتاوى متنوعة"]},{"id":18189,"question":"هل يحق للأب أن يحرم ابنه من الإرث؟ وإذا كان ذلك غير جائز، فما هو توجيهكم لبعض الآباء؟ جزاكم الله خيرًا.","title":"حكم حرمان الوالد أحد ورثته من الميراث","answer":"الجواب: ليس له أن يحرم أحدًا من الورثة من حقه، وليس له أن يوصي لأحد بزيادة؛ لقول النبي ﷺ: اتقوا الله واعدلوا بين أولادكم، فليس للأب أن يجور في العطية، ولما أعطى بعض الصحابة بعض أولاده غلامًا، قال له ﷺ: أعطيت ولدك كلهم مثل هذا؟ قال: لا، قال: إني لا أشهد على جور سماه: جورًا. فالمقصود؛ أن الواجب على الإنسان أن يعدل في العطية بين أولاده، للذكر مثل حظ الأنثيين، كالإرث، إلا إذا كانوا مرشدين وسمحوا أن يعطى واحدًا منهم، أو بعضهم شيئًا زائد فلا بأس، الحق لهم، إذا كانوا مرشدين، ليسوا صغارًا، مرشدين وسمحوا أن يعطى واحد زيادة عليهم، لأسباب رأوها؛ فلا بأس، وليس له أن يوصي أيضًا لأحدهم بالزيادة على إرثه؛ لقوله عليه الصلاة والسلام: لا وصية لوارث، إن الله قد أعطى كل ذي حقٍ حقه، فلا وصية لوارث، فليس له أن يوصي لبعض الأولاد بشيء زائد، أو لغيرهم من الورثة، لا الواجب تركهم على ما قسم الله، إن الله قد أعطى كل ذي حقٍ حقه، فلا وصية لوارث نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17226/حكم-حرمان-الوالد-احد-ورثته-من-الميراث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_731/nour_73113.mp3","categories":["الفرائض","الهبة والعطية"]},{"id":18247,"question":"في آخر أسئلة هذه السائلة، تقول سماحة الشيخ: أنا أحب معلمتي تذكر بأنها .. تقول السائلة: أنا أحب معلمتي في الله، وفي نهاية الدراسة أهديت لها هدية من باب التآلف والمحبة بيننا، هل يجوز لي هذا؟","title":"حكم الهدايا بين الطلاب والمدرسين","answer":"الجواب: ترك الهدية أحوط؛ لأنه قد يسبب الميل إليك دون بقية التلميذات، ترك الهدية أولى وأحوط؛ لأن المدرسة من العمال، ولا تنبغي الهدية للعمال، فالأحوط لك والذي ينبغي أن لا تهدي شيئًا؛ لأن هذه الهدية قد تسبب ميلًا من المدرسة إليك، وحيفًا على البقية بسبب الهدية، فالأحوط والذي يظهر من الأدلة عدم الهدية للمدرسات والمدرسين. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17296/حكم-الهدايا-بين-الطلاب-والمدرسين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78303.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":18283,"question":"ننتقل إلى رسالة أخرى وصلت من الأخوين: محمود فرحات، وعبد الرحمن الشدوي من الظهران، الإخوان لهم مجموعة من الأسئلة يسألون في سؤالهم الأول ويقولون:هناك عادة متبعة بين أفراد إحدى القبائل، تتمثل بأنه يجب على كل من يحضر ختان المولود الذكر دفع مبلغ من المال للوالد يتراوح من خمسين إلى مائة ريال، ما رأي سماحتكم في هذه العادة من الناحية الشرعية؟","title":"حكم دفع الأموال لمن رزق بمولود يوم ختانه","answer":"الجواب: إذا كان من عادة القبيلة، أو من عادة الأقارب بينهم الإهداء إلى أصحاب المولود في وقت الختان، أو في وقت العقيقة، أو في أي وقت بعد الولادة، فلا حرج في هذا من باب التبرع، ومن باب التعاون لا نعلم بأسًا في ذلك، كما أن من عادة الكثير من الناس مساعدة المتزوج إذا بلغهم أنه سيتزوج، أو دعاهم إلى الوليمة ساعدوه في الزواج؛ كل هذا من باب التعاون على الخير. والمسلمون شيء واحد يتعاونون على البر والتقوى وعلى مصالحهم وعلى سد حاجة الفقير، ولا سيما إذا كان صاحب المولود فقيرًا؛ فإن مساعدته من أهم القربات، لا في العقيقة ولا في غيرها. نعم.","link":"https://binbaz.org.sa/fatwas/17332/حكم-دفع-الاموال-لمن-رزق-بمولود-يوم-ختانه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_911/nour_91102.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":18368,"question":"من إحدى الأخوات المستمعات، تقول: أختكم في الإسلام (د. ع. ح) من العريش، أختنا لها قضيةٌ تقول فيها: سيدة كانت متزوجة، فمات عنها زوجها، وترك لها ولدين، ولم يترك لها أي مال، فتركت الأولاد لأهلهم، وتزوجت من رجلٍ آخر، وأنجبت منه ولدًا وبنتًا، ثم قام هذا الرجل الذي تزوجته بكتابة قطعة أرضٍ زراعية لها، فهل يجوز أن تكتب هذه الأرض باسم أولادها من هذا الرجل؛ لأنها أرض أبيهم في الأصل، أم تترك الأرض يرث فيها أولادها من الرجل الأول؟ جزاكم الله خيرًا.","title":"هل يجوز تخصيص بعض الأولاد بالعطية؟","answer":"الجواب: الواجب عليها ترك الأرض للجميع، فليس لها أن تخص أولادها من الزوج الجديد، الأرض تكون للجميع، تعدل بينهم؛ يقول النبي ﷺ: اتقوا الله، واعدلوا بين أولادكم ولو كانت الأرض من الزوج الجديد صارت ملكًا لها، فليس لها أن تعطيها أحدهم، وليس لها أن توصي بها لأحدهم، بل للجميع، تبقى في يدها، في ملكها، ويرثونها عنها، أو تقسمها بينهم لا بأس، أما أن تخص بها أحدًا منهم؛ فلا. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17435/هل-يجوز-تخصيص-بعض-الاولاد-بالعطية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_732/nour_73212.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":18814,"question":"هذا السائل أبو فهد من القصيم، يقول: شخص لديه زوجة، وقد تزوج بزوجة أخرى، وطلبت الأولى أن يعطيها من الحلي مثلما يعطي الزوجة الثانية، هل يلزمه هذا الشرط؟","title":"حكم إعطاء الزوجة الأولى مثل الثانية عند الزواج بها","answer":"الجواب: إذا كان الحلي مهرًا للجديدة لا يلزم، هذا مهر، أما إذا كان بعدما تزوجها أعطاها يعطي هذه مثلها من باب العدل، يكون كسوة وحلي بينهما يتماثلان، أما إذا كان الحلي مشروط في المهر إن كان لها حلي مشروطة في المهر أو دراهم مشروط هذا لا، هذه مهر ليست داخلة في النفقة، نعم. المقدم: جزاكم الله خيرًا فضيلة الشيخ.","link":"https://binbaz.org.sa/fatwas/17954/حكم-اعطاء-الزوجة-الاولى-مثل-الثانية-عند-الزواج-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79123.mp3","categories":["الهبة والعطية","تعدد الزوجات"]},{"id":19075,"question":"هذه أخت سائلة تقول: ما حكم تقديم الهدية بالنسبة للمعلمات يا سماحة الشيخ في آخر العام الدراسي؟","title":"حكم تقديم الطالبة هدية لمعلمتها","answer":"الجواب: تركه أولى لا، لا تعطي لا يعطين الهديات لا تقدم الطالبة هدية؛ لأن الهدية للمعلمة قد تفضي إلى المحاباة والحيف ولا ينبغي للمعلمة أن تقبل هدايا الطالبات؛ لأن هذا قد يفضي إلى اتهامها أو حيفها؛ ولأنها بمنزلة العمال وهدايا العمال غلول فينبغي للأمير والمعلم عدم قبول الهدايا ممن تحت يده حتى لا يجره ذلك إلى الحيف والظلم. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18246/حكم-تقديم-الطالبة-هدية-لمعلمتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88322.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":19230,"question":"يسأل أخونا أيضًا ويقول: لي أربع بنات وثلاثة أولاد، أولادي الكبار بنيت لكل منهم منزلًا خاصًا به، وابني الصغير لم أستطع أن أبني له منزلًا، وعندي منزل قديم سبق وأن منحته لزوجتي وبناتها الأربع في وصية رسمية، فهل للابن الأصغر حق شرعي في المنزل مع أمه وأخواته أم لا؟ أفيدوني جزاكم الله خيرًا.","title":"وجوب العدل بين الأولاد الكبار والصغار في العطية","answer":"الجواب: الواجب عليك يا أخي التعديل بين أولادك، الذكور والإناث؛ لقول النبي ﷺ: اتقوا الله واعدلوا بين أولادكم، فإذا كنت حين بنيت لأبنائك الكبار منازل قد وجد لك الولد الصغير والبنات وجب عليك التعديل، أما إن كنت بنيت لهم وأعطيتهم قبل وجود البنات وقبل وجود الابن الصغير فلا شيء عليك؛ لأنك ما عندك أولاد ذاك الوقت غيرهم، أما إن كان إعطاؤك لهم المنازل بعد وجود الابن الصغير، وبعد وجود البنات فالواجب التعديل، فإما أن تعطيهم مثل إخوانهم، لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11]، وإما أن ترجع في المنازل التي أعطيتها إخوانهم وتجعلها للجميع، بين الجميع أو لنفسك، وتبقى إرثًا لهم بعدك. وأما أن تخص أولئك بالمنازل أو البنات، هذا لا يجوز، بل عليك أن تعدل، وإذا أعطيت الأم وهي الزوجة شيئًا من مالك في صحتك فلا بأس، تخصها بشيء، لا بأس أن تخصها بشيء، وأما الأولاد ذكورهم وإناثهم فلا بد من التعديل بينهم، لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11]، في الأراضي وفي النقود وفي غير ذلك، هكذا أمر النبي ﷺ قال: اتقوا الله واعدلوا بين أولادكم. وليس لك أن توصي للزوجة ولا للبنات ولا غيرهم من الورثة وصية؛ لأن الورثة ليس لهم وصية، يقول النبي ﷺ: إن الله قد أعطى كل ذي حق حقه فلا وصية لوارث، ولكن لا مانع أن تعطي الزوجة في صحتك شيئًا من مالك في مقابل خدمتها ومعاشرتها الطيبة. وإذا كان لك زوجة أخرى تعطيها مثلها، وأما البنات وإخوتهم فلا بد من التعديل بينهم في المنازل وغيرها، إلا إذا سمحوا، إذا سمحت البنات عن إخوانهم وقالوا: ما نرغب في شيء وأنت مسامح، فلا بأس، وهكذا الابن الصغير إذا بلغ الحلم وسمح إذا كان رشيدًا وسمح، وقال: أنا سامح عن إخواني ولا لزوم للتعديل، فلا بأس الحق لهم، فإذا سمحوا سقط الوجوب الذي عليك. أما إن لم يسمحوا أو سمحوا سماحًا يخافون منك، ما هو بسماح عن رضا وعن طيب نفس ، لكن لأنك توعدهم أو يخشون من أمر يضرهم منك فالسماح الذي ليس له سند واضح، بل حصل عن خشية وخوف لا يعتبر، لا بد أن يكون سماح واضح من دون خوف منك ولا وعيد منك بل عن طيب نفس من أنفسهم، فلا بأس بذلك. نعم. المقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/18403/وجوب-العدل-بين-الاولاد-الكبار-والصغار-في-العطية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_889/nour_88902.mp3","categories":["تربية الأولاد","الهبة والعطية"]},{"id":19250,"question":"تسأل أختنا هل يجوز للمعلمة قبول الهدية من الطالبات؟ وإذا كان لا يجوز لها ذلك فهل يجوز قبولها بعد انتهاء العام الدراسي وتسليم النتائج؟ وإذا كان ذلك أيضًا لا يجوز، فهل يجوز لها قبولها من الطالبات بعد انتهاء مدة تدريسها في تلك المدرسة إذا أرادت الانتقال من هذه المدرسة لمدرسة أخرى؟","title":"حكم قبول الهدية من الطلاب","answer":"الجواب: الذي ينبغي للمعلمة ترك قبول الهدايا؛ لأنها قد تجرها إلى الحيف، وعدم النصح في حق من لم يهد والزيادة في حق المهدية والغش، فالأحوط للمؤمنة في هذا أن لا تقبل الهدية من الطالبات بالكلية؛ لأن ذلك قد يفضي إلى ما لا تحمد عقباه، والمؤمن يحتاط لدينه ويبتعد عن أسباب الريبة والخطر. أما بعد انتقالها من المدرسة إلى مدرسة أخرى فلا يضر ذلك؛ لأن الريبة قد انتهت حينئذ والخطر مأمون، وهكذا بعد فصلها من العمل إذا أهدوا إليها شيئًا فلا بأس. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18443/حكم-قبول-الهدية-من-الطلاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_738/nour_73813.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":19521,"question":"هل من توجيه كريم للآباء والأمهات في توجيه أولادهم في السن المبكرة لتعويدهم على الأمور الشرعية؟","title":"نصيحة للآباء والأمهات بتوجيه الأبناء في الأمور الشرعية","answer":"الجواب: نعم، الواجب على الآباء والأمهات تعليم الأولاد وتوجيههم إلى الخير، تعليم البنين والبنات، وإرشادهم فيما يتعلق بالصوم والصلاة، وما يتعلق بحيض المرأة وغير ذلك، يجب على الأب والأم إرشاد الأولاد يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا [التحريم:6]، الله جل وعلا أمرهم بهذا.\nوقال ﷺ: كلكم راع وكلكم مسئول عن رعيته، فالرجل راع في أهل بيته ومسئول عن رعيته، والمرأة راعية في بيت زوجها ومسئولة عن رعيتها كلهم راع. فالواجب على الأب أن يعتني بالأولاد وأن يرشدهم، وهكذا الأم، كلهم مسئولون فَوَرَبِّكَ لَنَسْأَلَنَّهُمْ أَجْمَعِينَ  ۝ عَمَّا كَانُوا يَعْمَلُونَ [الحجر:92، 93]. فالأب يعلم أولاده الذكور والإناث، والأم كذلك حتى ينشئوا على خير وعلى هدى وعلى بصيرة.\nنسأل الله للجميع الهداية. المقدم: اللهم آمين، أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18768/نصيحة-للاباء-والامهات-بتوجيه-الابناء-في-الامور-الشرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93934.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية","فتاوى متنوعة"]},{"id":19643,"question":"من جدة السائل (ع. ب. ي) يقول: سماحة الشيخ حفظكم الله، أنا متزوج من امرأة صالحة ولم يرزقني الله منها بولد، وقد أكد الأطباء على عدم قدرتها على الإنجاب ولا أملك غير البيت الذي نسكن فيه، فهل يمكنني أن أسجل البيت الذي نسكن فيه باسمها حتى يكون عونًا لها في حياتها، أم أن هذا محرم، علمًا بأنها زوجتي الوحيدة، ولا أنوي الزواج مرة أخرى ولي ستة من الإخوة والأخوات؟","title":"حكم الهبة للزوجة","answer":"الجواب: لا حرج في ذلك إذا أعطيتها بيتك وسجلته باسمها في صحتك فلا بأس، أما في حال المرض لا، أما في صحتك إذا أعطيتها بيتك أو أعطيتها شيئًا آخر من مالك فلا حرج في ذلك. نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18924/حكم-الهبة-للزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94932.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":19693,"question":"رجل له أربعة أولاد، منهم واحد موظف ومتزوج وله خمسة أولاد، وجزء من المال الذي بيد والده توفير من رواتب الولد المذكور، مع العلم بأن هذا الولد قائم بنفقة أولاده ووالديه وإخوانه؛ لأنهم في بيت واحد، فأحب والده أن يتبرع لابنه المذكور بخمس المال الذي بيده، مقابل عن عمله ودخله.","title":"هل للوالد أن يخص بعض أولاده بشيء دون الباقين؟","answer":"الجواب:\n\nقد ثبت عن النبي ﷺ أنه قال: اتقوا الله، واعدلوا بين أولادكم[1] متفق على صحته. فليس للوالد أن يخص بعض أولاده بشيء إلا برضا الباقين المكلفين المرشدين في أصح قولي العلماء. لكن إذا أحب أن يجعل ما قبضه من رواتبه في المستقبل قرضًا عليه، أو أمانة عنده، فلا بأس، وعليه أن يوضح ذلك في وثيقة معتمدة، وبذلك يكون قد حفظ له حقه الذي دخل عليه أو بعضه، ولا يكون أعطاه شيئًا، وإنما هو ماله حفظه له. والله أعلم[2].\n\n\n\n\tرواه البخاري في (الهبة وفضلها)، باب (الإشهاد في الهبة)، برقم: 2587، ومسلم في (الهبات)، باب (كراهة تفضيل بعض الأولاد في الهبة)، برقم: 1623.\n\tاستفتاء مقدم لسماحته من السائل /أ. ع. ن، وأجاب عنه سماحته برقم 841، في 25/3/1395هـ، عندما كان رئيسًا للجامعة الإسلامية. (مجموع فتاوى ومقالات الشيخ ابن باز 20/49).","link":"https://binbaz.org.sa/fatwas/19053/هل-للوالد-ان-يخص-بعض-اولاده-بشيء-دون-الباقين","audio":"","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":19694,"question":"في حالة اختلاف شخصين على مال، وتحكيم ثالث بينهما، واغتصاب الثالث شيئًا من هذا المال بموافقتنا هل يحل له ذلك أم يحرم عليه؟","title":"جواز قبول الهبة لفاعل المعروف","answer":"الجواب:\n\nإذا حكَّم شخصان ثالثًا بينهما في مالٍ، فأخذ منه شيئًا بإذنهما وموافقتهما فلا أعلم فيه بأسًا، ولا يسمى ذلك اغتصابًا، بل هو هبة منهما له. أما إن شرط عليهما أن لا يحكم بينهما إلا بجعل، فهذا في حله نظر وتفصيل[1].\n\n\n\n\tمجموع فتاوى ومقالات الشيخ ابن باز (20/62).","link":"https://binbaz.org.sa/fatwas/19089/جواز-قبول-الهبة-لفاعل-المعروف","audio":"","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":19718,"question":"تقول أختنا في رسالتها: في كل عام تأتيني هدايا بمناسبة عيد المعلم من بعض الطالبات، والحقيقة أنني لا أدري عن حكمها، فأرجوا إفادتي، بارك الله فيكم.","title":"حكم الهدية في عيد المعلم","answer":"الجواب: ليس له أصل، عيد المعلم ليس له أصل، ما للناس إلا أعياد معروفة، عيد الفطر وعيد الأضحى وأيام منى أيام عيد، ويوم عرفة يوم عيد، اجتماع المسلمين. أما عيد المعلم أو عيد الولد إذا جاء، ولد الإنسان يجعل له عيد -المولد- على رأس السنة، أو على رأس كل سنة، كل هذا لا أصل له، ما في أعياد لا موالد ولا غير موالد. الأعياد الشرعية معروفة: عيد الفطر وعيد الأضحى وما يتبعه من أيام التشريق، ويوم عرفة يوم حج عظيم، وفيه مجمع الناس، والعيد ما يعود ويتكرر بالشهر أو بالساعة أو بالأسبوع أو بالسنة؛ فالمسلمون لهم أعياد معروفة عيد الفطر، وعيد الأضحى، وأيام التشريق، وما يكون في ذلك من الأعمال، ويوم عرفة؛ لأنه يوم اجتماع الناس في الحج، هذه أعياد المسلمين، فجعل عيد غير ذلك لمولد ابنه أو عيد المعلم أو المعلمة هذا لا أصل له، وتعتبر من البدع. المقدم: إذن الهدايا التي تقدم في هذه المناسبة مثل مناسبة عيد المعلم؟ الشيخ: لا تقبل هذا، لا تقبليها، ولكن قولي لهم: لا يصلح هذا، ولا ينبغي أن يجعل عيد للمعلم. المقدم: إذن الهدايا في مثل هذا تكون بمثابة الرشوة؟ الشيخ: ما يصلح؛ لأنه إحياء لعيد منكر، وتقرير له.","link":"https://binbaz.org.sa/fatwas/28099/حكم-الهدية-في-عيد-المعلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/%D9%87%D8%AF%D8%A7%D9%8A%D8%A7%20%D8%B9%D9%8A%D8%AF%20%D8%A7%D9%84%D9%85%D8%B9%D9%84%D9%85.mp3","categories":["الهبة والعطية"]}]
